# ═══════════════════════════ ÇOKLU BOT (ANA BOT + KLONLAR) ═══════════════════════════
# Tüm botlar tek süreçte, aynı veritabanıyla çalışır. Modüldeki `bot` bir vekildir: işlem bir gruba/kanala
# yönelikse o sohbeti yöneten botu (channels.bot_id), değilse güncellemenin geldiği botu, o da yoksa ana botu kullanır.
_ctx_bot: contextvars.ContextVar = contextvars.ContextVar('ulus_ctx_bot', default=None)
MAIN_BOT: Bot = None
RUNNING_BOTS: dict = {}     # bot_id -> Bot (ana bot + çalışan klonlar)
CLONES: dict = {}           # bot_id -> klon kaydı (dict)
CLONE_APPS: dict = {}       # bot_id -> Application
_chat_bot_map: dict = {}    # chat_id -> yöneten bot_id (0 = eski kayıt → ana bot, -1 = sahipsiz)

def chat_bot_id(chat_id) -> int | None:
    """Sohbeti yöneten botun ID'si (bilinmiyorsa None)."""
    cid = str(chat_id)
    if cid not in _chat_bot_map:
        try:
            with get_db() as conn:
                row = conn.execute("SELECT bot_id FROM channels WHERE chat_id = ?", (cid,)).fetchone()
        except sqlite3.Error:
            row = None
        _chat_bot_map[cid] = (row['bot_id'] or 0) if row else None
    v = _chat_bot_map[cid]
    if v is None or v == -1:
        return None
    return v or BOT_ID or None

def set_chat_bot(chat_id, bot_id: int):
    with get_db() as conn:
        conn.execute("UPDATE channels SET bot_id = ? WHERE chat_id = ?", (bot_id, str(chat_id)))
        conn.commit()
    _chat_bot_map.pop(str(chat_id), None)

def cur_bot_id() -> int:
    """Şu an işlem yapan botun ID'si (güncellemenin geldiği bot; yoksa ana bot)."""
    b = _ctx_bot.get()
    return b.id if b is not None else BOT_ID

def bot_id_for(chat_id) -> int:
    """Bu sohbette işlem yapan botun ID'si (sohbeti yöneten çalışan bot; yoksa şu anki bot)."""
    b = chat_bot_id(chat_id)
    return b if b in RUNNING_BOTS else cur_bot_id()

def current_clone() -> dict | None:
    bid = cur_bot_id()
    return CLONES.get(bid) if bid and bid != BOT_ID else None

def bot_owner_id() -> int:
    c = current_clone()
    return c['owner_id'] if c else FOUNDER_ID

def is_bot_owner(user_id: int) -> bool:
    """Bu botun sahibi mi? Ana botta FOUNDER_ID; klonda klon sahibi (FOUNDER_ID her yerde yetkili)."""
    return bool(user_id) and user_id in (bot_owner_id(), FOUNDER_ID)

def brand() -> str:
    c = current_clone()
    return (c.get('brand') or c.get('name') or 'ULUS') if c else 'ULUS'

def _help_title() -> str:
    c = current_clone()
    return (c.get('help_title') or f"{brand()} Security Bot") if c else "ULUS Security Bot"

def brand_footer() -> str:
    """Klonlarda /start ve /help mesajının en altına ana bot imzası."""
    if not current_clone() or not MAIN_BOT:
        return ''
    try:
        return f"\n\n⚡ Main bot : @{MAIN_BOT.username}"
    except RuntimeError:
        return ''

def bot_chat_ids(bot_id: int | None = None) -> list:
    """Bu botun yönettiği kayıtlı sohbetler (ana bot için eski kayıtlar dahil)."""
    bid = bot_id or cur_bot_id()
    with get_db() as conn:
        if bid == BOT_ID:
            rows = conn.execute("SELECT chat_id FROM channels WHERE bot_id IS NULL OR bot_id IN (0, ?)", (bid,))
        else:
            rows = conn.execute("SELECT chat_id FROM channels WHERE bot_id = ?", (bid,))
        return [r['chat_id'] for r in rows]

class _BotProxy:
    """`bot.xxx(...)` çağrılarını doğru bota yönlendirir (bkz. yukarıdaki açıklama)."""
    def _pick(self, args, kwargs):
        cid = kwargs.get('chat_id', args[0] if args else None)
        if isinstance(cid, (int, str)) and str(cid).startswith('-'):
            b = RUNNING_BOTS.get(chat_bot_id(cid) or 0)
            if b is not None:
                return b
        return _ctx_bot.get() or MAIN_BOT

    def __getattr__(self, name):
        base = _ctx_bot.get() or MAIN_BOT
        if base is None:
            raise AttributeError(name)
        attr = getattr(base, name)
        if not asyncio.iscoroutinefunction(attr):
            return attr
        pick = self._pick

        async def call(*args, **kwargs):
            return await getattr(pick(args, kwargs), name)(*args, **kwargs)
        return call

    def __bool__(self):
        return (_ctx_bot.get() or MAIN_BOT) is not None

bot = _BotProxy()

# ═══════════════════════════ ÇOK DİL (i18n) ═══════════════════════════
# Kaynak dil Türkçe. Botun gönderdiği her metin (mesaj, açıklama, buton, açılır uyarı, komut menüsü) Telegram'a
# gitmeden hemen önce hedefin diline çevrilir: grup/kanal → grubun dili (/setlang), özel sohbet → kişinin dili.
# Katalog (dosyanın sonundaki I18N_* bölümleri) koddaki Türkçe metin satırlarından üretilir; ⟨0⟩ ⟨1⟩ değişken yerleridir,
# değişkenlerin değeri (isim, sayı, kullanıcı metni) aynen korunur. Katalogda olmayan satır Türkçe kalır.
# Yöneticinin yazdığı içerik (hoş geldin, kurallar, notlar, filtreler, duyurular) çevrilmez.
LANG_LABELS = {'tr': "🇹🇷 Türkçe", 'en': "🇬🇧 English", 'ru': "🇷🇺 Русский", 'uk': "🇺🇦 Українська",
               'az': "🇦🇿 Azərbaycanca", 'uz': "🇺🇿 Oʻzbekcha", 'kk': "🇰🇿 Қазақша", 'ar': "🇸🇦 العربية",
               'fa': "🇮🇷 فارسی", 'es': "🇪🇸 Español", 'pt': "🇧🇷 Português", 'id': "🇮🇩 Indonesia",
               'de': "🇩🇪 Deutsch", 'fr': "🇫🇷 Français", 'it': "🇮🇹 Italiano", 'hi': "🇮🇳 हिन्दी"}
DEFAULT_LANG = 'tr'
CMD_DEFAULT_LANG = 'en'   # Telegram uygulama dili desteklenmeyen kişiler komut menüsünü ve bot açıklamasını İngilizce görür
_LANG_OVERRIDE: contextvars.ContextVar = contextvars.ContextVar('ulus_lang', default=None)
_TR_SKIP: contextvars.ContextVar = contextvars.ContextVar('ulus_tr_skip', default=False)
_user_lang_cache: dict = {}
_cq_lang: dict = {}            # callback_query_id -> dil (açılır uyarılar için)
_I18N_SRC: dict = {}           # kimlik -> Türkçe şablon satırı
_I18N_TR: dict = {}            # dil -> {kimlik -> çeviri}
_I18N_IDX: dict = {}           # eşleştirme dizini (ilk kullanımda kurulur)
_tr_cache: dict = {}           # (dil, satır) -> çeviri
_PH = re.compile(r'⟨(\d+)⟩')

def _i18n_load():
    """Dosyanın sonundaki katalog bölümlerini okur (içe aktarmada bir kez)."""
    g = globals()
    for line in (g.get('I18N_SRC') or '').split('\n'):
        k, _, v = line.partition('\t')
        if k and v:
            _I18N_SRC[k] = v.replace('\\t', '\t')
    for name, val in g.items():
        if name.startswith('I18N_') and name != 'I18N_SRC' and isinstance(val, str) and len(name) <= 7:
            lang = name[5:].lower()
            d = {}
            for line in val.split('\n'):
                k, _, v = line.partition('\t')
                if k in _I18N_SRC and v:
                    d[k] = v.replace('\\t', '\t')
            if d:
                _I18N_TR[lang] = d

def available_langs() -> dict:
    return {k: v for k, v in LANG_LABELS.items() if k == DEFAULT_LANG or k in _I18N_TR}

# Değişken yeri bir HTML öğesini ortadan bölemez (isim boşluk içerse de <a …>Ali Veli</a> tek parça kalır)
_PH_UNIT = (r'(?:<a\b[^>]*>.*?</a>|<b>.*?</b>|<i>.*?</i>|<u>.*?</u>|<s>.*?</s>|<code>.*?</code>'
            r'|<tg-spoiler>.*?</tg-spoiler>|<[^>]*>|[^<])')
_TAG_PAIRS = (('<a ', '</a>'), ('<b>', '</b>'), ('<i>', '</i>'), ('<u>', '</u>'), ('<s>', '</s>'), ('<code>', '</code>'),
              ('<blockquote', '</blockquote>'), ('<tg-spoiler>', '</tg-spoiler>'), ('<pre>', '</pre>'))
_TAGS = re.compile(r'<[^>]+>')

def _i18n_index():
    """Şablonlardan tam eşleşme sözlüğü ve kalıp (regex) kovaları kurar. HTML kaçışlı ve etiketsiz hâller de eklenir."""
    if _I18N_IDX:
        return _I18N_IDX
    exact, buckets, wild = {}, {}, []
    for k, src in _I18N_SRC.items():
        variants = [(src, None)]
        esc = html.escape(src, quote=False)
        if esc != src:
            variants.append((esc, 'esc'))
        escq = html.escape(src)
        if escq != esc:
            variants.append((escq, 'escq'))
        plain = _TAGS.sub('', src).strip()
        if plain != src and _LETTERS.search(_PH.sub('', plain)):
            variants.append((plain, 'plain'))
        for text, form in variants:
            if not _PH.search(text):
                exact.setdefault(text, (k, form))
                continue
            parts = _PH.split(text)          # [sabit, no, sabit, no, ...]
            rx, order = '', []
            for i, p in enumerate(parts):
                if i % 2 == 0:
                    rx += re.escape(p)
                else:
                    order.append(int(p))
                    rx += f'({_PH_UNIT}*?)' if i < len(parts) - 2 or parts[-1] else f'({_PH_UNIT}*)'
            static = ''.join(parts[0::2])
            entry = (re.compile(rx, re.S), k, form, order, len(static))
            if parts[0][:3].strip() and len(parts[0]) >= 3:
                buckets.setdefault(('p', parts[0][:3]), []).append(entry)
            elif len(parts[-1]) >= 3 and parts[-1][-3:].strip():
                buckets.setdefault(('s', parts[-1][-3:]), []).append(entry)
            elif _LETTERS.search(static):
                wild.append(entry)
    for v in buckets.values():
        v.sort(key=lambda e: -e[4])
    wild.sort(key=lambda e: -e[4])
    _I18N_IDX.update(exact=exact, buckets=buckets, wild=wild)
    return _I18N_IDX

def _tr_dst(lang: str, k: str, form: str | None) -> str | None:
    t = _I18N_TR.get(lang, {}).get(k)
    if t is None and lang != 'en':
        t = _I18N_TR.get('en', {}).get(k)  # bu dilde henüz çevrilmemiş satır: Türkçe yerine İngilizcesi
    if t is None:
        return None
    if form == 'esc':
        return html.escape(t, quote=False)
    if form == 'escq':
        return html.escape(t)
    if form == 'plain':
        return _TAGS.sub('', t).strip()
    return t

def _balanced(v: str) -> bool:
    if '<' not in v:
        return True
    return all(v.count(o) == v.count(c) for o, c in _TAG_PAIRS)

_DECOR_WRAP = re.compile(r'^((?:<(?:b|i|u|s|code|tg-spoiler|blockquote(?: expandable)?)>)+)(.*?)'
                         r'((?:</(?:b|i|u|s|code|tg-spoiler|blockquote)>)*)$', re.S)
_DECOR_CLOSE = re.compile(r'^(.*?)((?:</(?:b|i|u|s|code|tg-spoiler|blockquote)>)+)$', re.S)
_DECOR_LEAD = re.compile(r'^([^\w<&{(\[/@#"\'«]+)(.+)$', re.S)
_DECOR_TRAIL = re.compile(r'^(.*?[^\s])(\s*[^\w\s<>&;()\[\]{}"\'«»%/@#.,!?…+\-]+)$', re.S)
_DECOR_MENTION = re.compile(r'^(<a\b[^>]*>.*?</a>[\s,:]*)(.+)$', re.S)
_DECOR_PAREN = re.compile(r'^(.*?)(\s*\()([^()]+)(\)[.!]?)$', re.S)
_DECOR_NUM_TAIL = re.compile(r'^(.*?[^\d\s.,:/%+\-])(\s+[\d.,:/%+\-]+)$', re.S)
_DECOR_NUM_HEAD = re.compile(r'^([\d.,:/%+\-]+\s+)(.*[^\W\d_].*)$', re.S)
_SEPS = (' · ', ' | ', ' — ', ' – ', ': ', ' → ')
_LETTERS = re.compile(r'[^\W\d_]{2,}')

def _tr_core(s: str, lang: str, depth: int) -> str | None:
    """Tam satır eşleşmesi (sabit metin ya da değişkenli kalıp). Bulunamazsa None."""
    idx = _i18n_index()
    hit = idx['exact'].get(s)
    if hit:
        return _tr_dst(lang, *hit)
    if len(s) > 1500:
        return None
    cands = idx['buckets'].get(('p', s[:3]), []) + idx['buckets'].get(('s', s[-3:]), []) + idx['wild']
    for rx, k, form, order, _ in cands:
        m = rx.fullmatch(s)
        if not m or not all(_balanced(g) for g in m.groups()):
            continue
        dst = _tr_dst(lang, k, form)
        if dst is None:
            return None
        vals = {}
        for n, v in zip(order, m.groups()):
            vals[n] = _tr_value(v, lang, depth + 1)
        return _PH.sub(lambda mm: vals.get(int(mm.group(1)), mm.group(0)), dst)
    return None

def _tr_value(v: str, lang: str, depth: int) -> str:
    """Kalıptaki değişkenin değeri: sadece bilinen etiketler çevrilir (isimler, sayılar, kullanıcı metni aynen kalır)."""
    if depth > 3 or not v or not _LETTERS.search(v) or len(v) > 600:
        return v
    s = v.strip()
    t = _tr_any(s, lang, depth)
    if t is None and ', ' in s:
        parts = s.split(', ')
        tp = [(_tr_core(p.strip(), lang, depth) or p) for p in parts]
        t = ', '.join(tp) if tp != parts else None
    if t is None:
        return v
    return v[:len(v) - len(v.lstrip())] + t + v[len(v.rstrip()):]

_WORDS = re.compile(r'[^\W\d_]{2,}')

def _residue(out: str, src: str) -> int:
    """Çeviride kaynaktan aynen kalan kelime sayısı (iki adaydan iyisini seçmek için; isimler ikisinde de aynıdır)."""
    sw = set(_WORDS.findall(_TAGS.sub(' ', src)))
    return sum(1 for w in _WORDS.findall(_TAGS.sub(' ', out)) if w in sw)

def _tr_any(s: str, lang: str, depth: int, seps: tuple = _SEPS, level: int = 0) -> str | None:
    """Kalıp eşleşmesi ile süs/ayraç ayrıştırmasından daha çok kelimeyi çevireni seçer
    ('Koruma susturması: 60 dk' → 'Koruma ⟨0⟩' kalıbı yerine 'Koruma susturması' + '60 dk')."""
    t = _tr_core(s, lang, depth)
    if t is not None and not _residue(t, s):
        return t
    alt = _tr_decor(s, lang, depth, seps, level)
    if t is None or (alt is not None and _residue(alt, s) < _residue(t, s)):
        return alt
    return t

def _lead_splits(prefix: str):
    """'❌ 🚩 ' → ['❌ ', '❌ 🚩 '] (önce kısa önek: katalogdaki satır emojiyle başlayabilir)"""
    cuts = [i + 1 for i, ch in enumerate(prefix) if ch.isspace() and i + 1 < len(prefix)]
    return [prefix[:i] for i in cuts] + [prefix]

def _tr_decor(s: str, lang: str, depth: int, seps: tuple = _SEPS, level: int = 0) -> str | None:
    """Süslemeleri (kalın/alıntı etiketleri, baştaki/sondaki emoji ve madde işaretleri, baştaki @bahsetme, sondaki
    parantez) ayırıp tekrar dener; ayraçlardan (· | — : →) böler. Adaylardan en çok kelimeyi çevireni seçilir."""
    if level > 6:
        return None
    best = [None, None]

    def offer(t):
        if t is None:
            return False
        r = _residue(t, s)
        if best[0] is None or r < best[1]:
            best[0], best[1] = t, r
        return r == 0

    sub = lambda x, sp=seps: _tr_any(x, lang, depth, sp, level + 1)
    m = _DECOR_WRAP.match(s)
    if m and m.group(2).strip():
        t = sub(m.group(2).strip())
        if t is not None and offer(m.group(1) + t + m.group(3)):
            return best[0]
    m = _DECOR_CLOSE.match(s)
    if m and m.group(1).strip():
        t = sub(m.group(1).strip())
        if t is not None and offer(m.group(1)[:len(m.group(1)) - len(m.group(1).lstrip())] + t + m.group(2)):
            return best[0]
    m = _DECOR_MENTION.match(s)
    if m and _LETTERS.search(m.group(2)):
        t = sub(m.group(2))
        if t is not None and offer(m.group(1) + t):
            return best[0]
    m = _DECOR_LEAD.match(s)
    if m and _LETTERS.search(m.group(2)):
        whole = m.group(1)
        for pre in _lead_splits(whole):
            rest = s[len(pre):]
            if not rest.strip() or rest == s:
                continue
            t = _tr_core(rest, lang, depth) if pre != whole else sub(rest)
            if t is not None and offer(pre + t):
                return best[0]
    m = _DECOR_TRAIL.match(s)
    if m and _LETTERS.search(m.group(1)):
        t = sub(m.group(1))
        if t is not None and offer(t + m.group(2)):
            return best[0]
    m = _DECOR_PAREN.match(s)
    if m and (_LETTERS.search(m.group(3)) or _LETTERS.search(m.group(1))):
        head = sub(m.group(1)) if _LETTERS.search(m.group(1)) else None
        whole = _tr_core('(' + m.group(3) + ')', lang, depth) if _LETTERS.search(m.group(3)) else None
        if whole is not None and whole.startswith('(') and whole.endswith(')'):
            inner = whole[1:-1]
        else:
            inner = sub(m.group(3).strip(), _SEPS) if _LETTERS.search(m.group(3)) else None
        if (head is not None or inner is not None) and offer(
                (head if head is not None else m.group(1)) + m.group(2) + (inner if inner is not None else m.group(3))
                + m.group(4)):
            return best[0]
    m = _DECOR_NUM_TAIL.match(s)
    if m and _LETTERS.search(m.group(1)):
        t = sub(m.group(1))
        if t is not None and offer(t + m.group(2)):
            return best[0]
    m = _DECOR_NUM_HEAD.match(s)
    if m and _LETTERS.search(m.group(2)):
        t = sub(m.group(2))
        if t is not None and offer(m.group(1) + t):
            return best[0]
    for i, sep in enumerate(seps):
        if sep in s:
            parts = s.split(sep)
            rest = seps[i + 1:]
            out = [(sub(p.strip(), rest) or p.strip()) if _LETTERS.search(p) else p.strip() for p in parts]
            if out != [p.strip() for p in parts] and offer(sep.join(out)):
                return best[0]
            break
    return best[0]

def _plural_slavic(n: int, forms: tuple) -> str:
    """1 день · 2 дня · 5 дней"""
    n = abs(n) % 100
    if 11 <= n <= 14:
        return forms[2]
    n %= 10
    return forms[0] if n == 1 else forms[1] if 2 <= n <= 4 else forms[2]

_RU_FORMS = [('день', 'дня', 'дней'), ('час', 'часа', 'часов'), ('минута', 'минуты', 'минут'), ('мин', 'мин', 'мин'),
             ('секунда', 'секунды', 'секунд'), ('сообщение', 'сообщения', 'сообщений'), ('участник', 'участника', 'участников'),
             ('человек', 'человека', 'человек'), ('предупреждение', 'предупреждения', 'предупреждений'),
             ('раз', 'раза', 'раз'), ('неделя', 'недели', 'недель'), ('месяц', 'месяца', 'месяцев'), ('год', 'года', 'лет'),
             ('кнопка', 'кнопки', 'кнопок'), ('вариант', 'варианта', 'вариантов'), ('группа', 'группы', 'групп'),
             ('канал', 'канала', 'каналов'), ('действие', 'действия', 'действий'), ('голос', 'голоса', 'голосов'),
             ('победитель', 'победителя', 'победителей'), ('клик', 'клика', 'кликов'), ('ссылка', 'ссылки', 'ссылок')]
_UK_FORMS = [('день', 'дні', 'днів'), ('година', 'години', 'годин'), ('хвилина', 'хвилини', 'хвилин'),
             ('секунда', 'секунди', 'секунд'), ('повідомлення', 'повідомлення', 'повідомлень'),
             ('учасник', 'учасники', 'учасників'), ('людина', 'людини', 'людей'),
             ('попередження', 'попередження', 'попереджень'), ('раз', 'рази', 'разів'), ('тиждень', 'тижні', 'тижнів'),
             ('місяць', 'місяці', 'місяців'), ('рік', 'роки', 'років'), ('кнопка', 'кнопки', 'кнопок'),
             ('група', 'групи', 'груп'), ('канал', 'канали', 'каналів'), ('дія', 'дії', 'дій')]

def _slavic_fixer(table):
    by_word = {f: forms for forms in table for f in forms}
    rx = re.compile(r'(?<![\d.,])(\d+) (' + '|'.join(sorted(by_word, key=len, reverse=True)) + r')\b')
    return lambda t: rx.sub(lambda m: f"{m.group(1)} {_plural_slavic(int(m.group(1)), by_word[m.group(2)])}", t)

_EN_ONE = re.compile(r'(?<![\d.,])\b1 (minute|hour|day|second|message|member|warning|time|week|month|year|channel|group|'
                     r'user|button|option|link|action|admin|ban|mute|report|vote|winner|click|sticker|photo|video|file|'
                     r'reply|word|note|filter|request|clone|chat|invite|join|entry)s\b')
_POSTFIX = {
    'en': lambda t: _EN_ONE.sub(r'1 \1', t).replace('1 people', '1 person').replace('1 entries', '1 entry'),
    'ru': _slavic_fixer(_RU_FORMS),
    'uk': _slavic_fixer(_UK_FORMS),
}

def tr_line(line: str, lang: str) -> str:
    if not line or lang not in _I18N_TR or not _LETTERS.search(line):
        return line
    key = (lang, line)
    if key in _tr_cache:
        return _tr_cache[key]
    s = line.strip()
    t = _tr_any(s, lang, 0)
    if t is not None and lang in _POSTFIX:
        t = _POSTFIX[lang](t)
    out = line if t is None else line[:len(line) - len(line.lstrip())] + t + line[len(line.rstrip()):]
    if len(_tr_cache) > 20000:
        _tr_cache.clear()
    _tr_cache[key] = out
    return out

def tr_text(text: str, lang: str | None) -> str:
    """Çok satırlı metni hedef dile çevirir (her satır ayrı eşleşir)."""
    if not text or not lang or lang == DEFAULT_LANG or lang not in _I18N_TR:
        return text
    return '\n'.join(tr_line(ln, lang) for ln in text.split('\n'))

def L(text: str, lang: str | None) -> str:
    """Kod içinden açık çeviri (grafik etiketleri, web panel, açıklamalar)."""
    return tr_text(text, lang)

class lang_override:
    """with lang_override('en'): ... — bu blokta gönderilenler bu dile çevrilir (log kanalı, komut menüsü)."""
    def __init__(self, lang):
        self.lang, self.tok = lang, None

    def __enter__(self):
        self.tok = _LANG_OVERRIDE.set(self.lang)
        return self

    def __exit__(self, *a):
        _LANG_OVERRIDE.reset(self.tok)

def user_lang_set(uid) -> str | None:
    """Kişinin seçtiği dil (seçmediyse None)."""
    try:
        uid = int(uid)
    except (TypeError, ValueError):
        return None
    if uid not in _user_lang_cache:
        try:
            with get_db() as conn:
                r = conn.execute("SELECT lang FROM user_lang WHERE user_id = ?", (uid,)).fetchone()
        except sqlite3.Error:
            r = None
        _user_lang_cache[uid] = r['lang'] if r else None
        if len(_user_lang_cache) > 50000:
            _user_lang_cache.clear()
    return _user_lang_cache[uid]

def user_lang(uid) -> str:
    return user_lang_set(uid) or DEFAULT_LANG

def set_user_lang(uid: int, lang: str):
    with get_db() as conn:
        conn.execute("INSERT OR REPLACE INTO user_lang (user_id, lang, at) VALUES (?, ?, ?)", (uid, lang, time.time()))
    _user_lang_cache[uid] = lang

_log_lang_cache: dict = {}

def _log_owner_lang(cid: str) -> str | None:
    """Bu sohbet bir grubun log kanalıysa o grubun dili (5 dk önbellek)."""
    hit = _log_lang_cache.get(cid)
    if hit and time.time() - hit[0] < 300:
        return hit[1]
    lang = None
    try:
        with get_db() as conn:
            rows = conn.execute("SELECT settings FROM channels WHERE log_chat_id = ? LIMIT 20", (cid,)).fetchall()
        for r in rows:
            lang = (json.loads(r['settings'] or '{}') or {}).get('lang')
            if lang:
                break
    except (sqlite3.Error, ValueError, TypeError):
        lang = None
    if len(_log_lang_cache) > 5000:
        _log_lang_cache.clear()
    _log_lang_cache[cid] = (time.time(), lang)
    return lang

def chat_lang(chat_id) -> str:
    """Grup/kanal → grubun dili (log kanalı → bağlı olduğu grubun dili); özel sohbet → kişinin dili."""
    try:
        cid = int(chat_id)
    except (TypeError, ValueError):
        return DEFAULT_LANG
    if cid < 0:
        ch = get_channel_settings(str(cid))
        return ((ch or {}).get('settings') or {}).get('lang') or _log_owner_lang(str(cid)) or DEFAULT_LANG
    return user_lang(cid)

_TR_SEND_KEYS = {'text': 4096, 'caption': 1024}

def _tr_markup(markup, lang: str):
    if isinstance(markup, InlineKeyboardMarkup):
        rows, changed = [], False
        for row in markup.inline_keyboard:
            r2 = []
            for b in row:
                t = tr_line(b.text, lang)
                if t != b.text:
                    d = b.to_dict()
                    d['text'], changed = t, True
                    b = InlineKeyboardButton.de_json(d, None)
                r2.append(b)
            rows.append(r2)
        return InlineKeyboardMarkup(rows) if changed else markup
    if isinstance(markup, ReplyKeyboardMarkup):
        d = markup.to_dict()
        for row in d.get('keyboard', []):
            for b in row:
                if isinstance(b, dict) and b.get('text'):
                    b['text'] = tr_line(b['text'], lang)
        if d.get('input_field_placeholder'):
            d['input_field_placeholder'] = tr_line(d['input_field_placeholder'], lang)[:64]
        return ReplyKeyboardMarkup.de_json(d, None)
    if isinstance(markup, ForceReply) and markup.input_field_placeholder:
        return ForceReply(selective=markup.selective,
                          input_field_placeholder=tr_line(markup.input_field_placeholder, lang)[:64])
    return markup

def _request_lang(endpoint: str, data: dict) -> str | None:
    o = _LANG_OVERRIDE.get()
    if o:
        return o
    if endpoint == 'answerCallbackQuery':
        return _cq_lang.get(str(data.get('callback_query_id')))
    if endpoint in ('setMyCommands', 'setMyDescription', 'setMyShortDescription'):
        return data.get('language_code')
    if 'chat_id' in data:
        return chat_lang(data['chat_id'])
    return None

def i18n_request(endpoint: str, data: dict, lang: str) -> dict:
    """Telegram'a gidecek isteğin metinlerini çevirir (yeni sözlük döner; çeviri yoksa aynısı)."""
    if not lang or lang == DEFAULT_LANG or lang not in _I18N_TR or data.get('entities') or data.get('caption_entities'):
        return data
    new = dict(data)
    if not _TR_SKIP.get():
        for key, limit in _TR_SEND_KEYS.items():
            if isinstance(new.get(key), str):
                t = tr_text(new[key], lang)
                if endpoint == 'answerCallbackQuery':
                    t = t[:200]
                if len(t) <= limit:
                    new[key] = t
    if new.get('reply_markup') is not None:
        new['reply_markup'] = _tr_markup(new['reply_markup'], lang)
    if endpoint == 'setMyCommands' and new.get('commands'):
        new['commands'] = [BotCommand(c.command, tr_line(c.description, lang)[:256]) for c in new['commands']]
    for key, limit in (('description', 512), ('short_description', 120)):
        if isinstance(new.get(key), str):
            new[key] = tr_text(new[key], lang)[:limit]
    return new if any(new.get(k) is not data.get(k) for k in new) else data

_ORIG_DO_POST = ExtBot._do_post

async def _i18n_do_post(self, endpoint, data, *args, **kwargs):
    try:
        lang = _request_lang(endpoint, data)
        new = i18n_request(endpoint, data, lang) if lang and lang != DEFAULT_LANG else data
    except Exception as e:  # çeviri hiçbir zaman gönderimi engellemesin
        logger.debug(f"Çeviri hatası ({endpoint}): {e}")
        new = data
    if new is data:
        return await _ORIG_DO_POST(self, endpoint, data, *args, **kwargs)
    try:
        return await _ORIG_DO_POST(self, endpoint, new, *args, **kwargs)
    except BadRequest as e:
        low = str(e).lower()
        if any(w in low for w in ("parse", "entit", "too long", "button", "tag")):
            logger.warning(f"Çeviri gönderilemedi, Türkçe gönderiliyor ({endpoint}, {lang}): {e}")
            return await _ORIG_DO_POST(self, endpoint, data, *args, **kwargs)
        raise

ExtBot._do_post = _i18n_do_post

def note_callback_lang(update) -> None:
    q = update.callback_query
    if q is None:
        return
    m = q.message
    chat = getattr(m, 'chat', None) if m is not None else None
    _cq_lang[str(q.id)] = chat_lang(chat.id) if chat is not None else user_lang(q.from_user.id)
    if len(_cq_lang) > 5000:
        for k in list(_cq_lang)[:2500]:
            _cq_lang.pop(k, None)

