def _btn_source(b: dict) -> str:
    target = {'url': b['v'], 'rules': 'rules', 'note': f"#{b['v']}", 'popup': f"popup:{b['v']}"}.get(b['k'], b['v'])
    color = {str(GREEN): ' #yeşil', str(RED): ' #kırmızı', str(BLUE): ' #mavi'}.get(str(b.get('c')), '')
    return f"{b['t']} - {target}{color}"

def rich_to_source(rich: dict | None) -> str:
    """Kayıtlı zengin mesaj → panelde düzenlenen yazı (izinli HTML etiketleri + buton satırları + %%%)."""
    parts = []
    for v in (rich or {}).get('v') or []:
        lines = [html.unescape(v.get('text') or '')] if v.get('text') else []
        lines += [" && ".join(_btn_source(b) for b in row) for row in v.get('buttons') or []]
        parts.append("\n".join(lines))
    return "\n%%%\n".join(p for p in parts if p)

_WEB_TAG = re.compile(r'&lt;(/?(?:b|i|u|s|code|pre|tg-spoiler|blockquote(?: expandable)?)|a href="https?://[^"<>]+"|/a'
                      r'|tg-emoji emoji-id="\d+"|/tg-emoji)&gt;')

def source_to_html(src: str) -> str:
    """Panel yazısı → HTML: her şey kaçışlanır, sadece izinli etiketler geri açılır."""
    return _WEB_TAG.sub(lambda m: f"<{html.unescape(m.group(1))}>", html.escape(src or '', quote=False))

def _rich_kind(key: str) -> str:
    return key[:-5]  # welcome_rich → welcome

def _field_value(key: str, ftype: str, s: dict):
    if ftype == 'rich':
        kind = _rich_kind(key)
        rich = welcome_rich(s) if kind == 'welcome' else goodbye_rich(s) if kind == 'goodbye' else rules_rich(s)
        media = (rich or {}).get('m')
        return {'text': rich_to_source(rich), 'media': RICH_MEDIA_LABELS.get(media['type'], media['type']) if media else None}
    if ftype in ('list', 'ids'):
        return "\n".join(str(x) for x in s.get(key) or [])
    default = _default_channel_settings().get(key)
    v = s.get(key, default)
    return bool(v) if ftype == 'bool' else v

def _validate_field(f: dict, value, s: dict):
    """Dönüş: (yeni değer, hata). Rich alanlar (kind, rich) döndürür."""
    t = f['type']
    if t == 'bool':
        return bool(value), None
    if t == 'select':
        allowed = {str(o[0]): o[0] for o in f['options']}
        if str(value) not in allowed:
            return None, "Geçersiz seçim"
        return allowed[str(value)], None
    if t == 'list':
        items = [x.strip() for x in str(value or '').split('\n') if x.strip()][:500]
        out = []
        for it in items:
            if len(it) > 100:
                return None, f"Çok uzun: {it[:20]}…"
            if f['key'] == 'banned_words':
                if it.lower().startswith('re:'):
                    try:
                        re.compile(it[3:])
                    except re.error:
                        return None, f"Geçersiz regex: {it}"
                else:
                    it = it.lower()
            else:
                it = re.sub(r'^[a-z]+://', '', it.lower())
                it = it[4:] if it.startswith('www.') else it
            if it not in out:
                out.append(it)
        return out, None
    if t == 'ids':
        out = []
        for it in str(value or '').replace(',', '\n').split('\n'):
            it = it.strip().lstrip('@')
            if not it:
                continue
            if not re.fullmatch(r'\d{3,15}', it) or not valid_id(int(it)):
                return None, f"Geçersiz ID: {it[:20]} (sadece sayı)"
            if int(it) not in out:
                out.append(int(it))
        limit = 3 if f['key'] == 'recovery_ids' else 500
        if len(out) > limit:
            return None, f"En fazla {limit} kişi"
        return out, None
    if t == 'rich':
        if not isinstance(value, dict):
            return None, "Geçersiz"
        src = str(value.get('text') or '')[:6000]
        kind = _rich_kind(f['key'])
        old = welcome_rich(s) if kind == 'welcome' else goodbye_rich(s) if kind == 'goodbye' else rules_rich(s)
        media = None if value.get('remove_media') else (old or {}).get('m')
        rich = build_rich(source_to_html(src), media)
        if kind == 'rules' and not rich_plain(rich) and not media:
            return ('rules', None), None  # boş kurallar = sil
        if kind != 'rules' and not rich_plain(rich) and not media:
            return None, "Mesaj boş olamaz"
        return (kind, rich), None
    return None, "Bilinmeyen alan"

# ── Web panel: ayar dışı bölümler (gece modu, notlar, filtreler, zamanlanmış mesajlar, engelli medya, yetkililer) ──
WEB_TEXT_MAX = 6000
WEB_SCHED_INTERVALS = [[1800, "30 dakikada bir"], [3600, "Saatte bir"], [7200, "2 saatte bir"], [10800, "3 saatte bir"],
                       [21600, "6 saatte bir"], [43200, "12 saatte bir"], [86400, "Günde bir"], [259200, "3 günde bir"],
                       [604800, "Haftada bir"]]

def _web_has(chat_id: str, uid: int, perm: str) -> bool:
    if perm == 'kurucu':
        return user_level(chat_id, uid) >= LVL_KURUCU
    return has_specific_permission(chat_id, uid, perm)

def _hm(h: int, m: int) -> str:
    return f"{int(h):02d}:{int(m):02d}"

def web_extras(chat_id: str, uid: int) -> dict:
    flush_writes()
    nm = _nm_data(chat_id)
    channel = get_channel_settings(chat_id)
    week = time.time() - 7 * 86400
    with get_db() as conn:
        notes = [{'name': r['name'], 'preview': (_strip_html(r['content'] or '')[:90]
                                                 or (f"🖼 {r['file_type']}" if r['file_id'] else ''))}
                 for r in conn.execute("SELECT name, content, file_id, file_type FROM notes WHERE chat_id = ? ORDER BY name",
                                       (chat_id,))]
        flt = [{'key': r['trigger_norm'], 'trigger': r['trigger_text'], 'contains': r['mode'] == 'contains',
                'preview': (_strip_html(r['reply_text'] or '')[:90] or (f"🖼 {r['file_type']}" if r['file_id'] else ''))}
               for r in conn.execute("SELECT * FROM chat_filters WHERE chat_id = ? ORDER BY trigger_text", (chat_id,))]
        blocked = [{'id': r['rowid'], 'label': (f"📦 Sticker paketi: {r['uid'][4:]}" if r['kind'] == 'set'
                                                else f"🖼 {r['note'] or r['kind']}")[:80]}
                   for r in conn.execute("SELECT rowid, uid, kind, note FROM blocked_media WHERE chat_id = ? "
                                         "ORDER BY added_at DESC LIMIT 200", (chat_id,))]
        staff = [{'name': r['fn'] or str(r['user_id']), 'id': r['user_id'], 'role': ROLE_NAMES.get(r['role'], r['role'])}
                 for r in conn.execute(
                     "SELECT r.user_id, r.role, (SELECT first_name FROM users u WHERE u.user_id = r.user_id "
                     "ORDER BY last_seen DESC LIMIT 1) fn FROM roles r WHERE r.chat_id = ?", (chat_id,))]
        order = {k: i for i, k in enumerate(ROLE_NAMES)}
        staff.sort(key=lambda x: order.get(next((k for k, v in ROLE_NAMES.items() if v == x['role']), ''), 99))
        stats = {
            'msgs': conn.execute("SELECT COUNT(*) FROM message_stats WHERE chat_id = ? AND sent_at >= ?",
                                 (chat_id, week)).fetchone()[0],
            'active': conn.execute("SELECT COUNT(DISTINCT user_id) FROM message_stats WHERE chat_id = ? AND sent_at >= ?",
                                   (chat_id, week)).fetchone()[0],
            'joins': conn.execute("SELECT COUNT(*) FROM member_events WHERE chat_id = ? AND kind = 'join' AND at >= ?",
                                  (chat_id, week)).fetchone()[0],
            'warns': conn.execute("SELECT COUNT(*) FROM warnings WHERE chat_id = ? AND warn_count > 0",
                                  (chat_id,)).fetchone()[0],
            'bans': conn.execute("SELECT COUNT(*) FROM ban_list WHERE chat_id = ?", (chat_id,)).fetchone()[0],
        }
        log_id = (channel or {}).get('log_chat_id')
        log_row = conn.execute("SELECT title FROM channels WHERE chat_id = ?", (str(log_id),)).fetchone() if log_id else None
    sched = []
    for r in sched_list(chat_id):
        try:
            rich = json.loads(r['rich'])
        except ValueError:
            rich = {}
        sched.append({'id': r['id'], 'preview': rich_plain(rich, 90) or "(medya)", 'every': human_duration(r['interval']),
                      'enabled': bool(r['enabled']),
                      'next': datetime.fromtimestamp(r['next_at'], TZ_TR).strftime('%d.%m %H:%M')})
    return {
        'night': {'enabled': bool(nm['enabled']), 'active': bool(nm['is_active']),
                  'start': _hm(nm['start_hour'], nm['start_minute']), 'end': _hm(nm['end_hour'], nm['end_minute']),
                  'restrictions': [[k, lbl, bool(nm['restrictions'].get(k))] for k, lbl in NIGHT_RESTRICTIONS],
                  'editable': _web_has(chat_id, uid, 'can_manage_settings')},
        'notes': {'items': notes, 'editable': _web_has(chat_id, uid, 'can_content')},
        'filters': {'items': flt, 'editable': _web_has(chat_id, uid, 'can_filters'), 'limit': FILTER_LIMIT},
        'sched': {'items': sched, 'editable': _web_has(chat_id, uid, 'can_content'), 'intervals': WEB_SCHED_INTERVALS},
        'blocked': {'items': blocked, 'editable': _web_has(chat_id, uid, 'can_manage_settings')},
        'staff': staff,
        'stats': stats,
        'log': ((log_row['title'] if log_row and log_row['title'] else str(log_id)) if log_id else None),
    }

def _parse_hm(v) -> tuple | None:
    m = re.fullmatch(r'(\d{1,2}):(\d{2})', str(v or '').strip())
    if not m or int(m.group(1)) > 23 or int(m.group(2)) > 59:
        return None
    return int(m.group(1)), int(m.group(2))

def web_op(chat_id: str, uid: int, body: dict):
    """Panelden tek işlem (not/filtre/zamanlı mesaj ekle-sil, gece modu, engelli medya). Dönüş: (mesaj, hata)."""
    op = str(body.get('op') or '')
    need = {'night': 'can_manage_settings', 'note_add': 'can_content', 'note_del': 'can_content',
            'filter_add': 'can_filters', 'filter_del': 'can_filters', 'sched_add': 'can_content',
            'sched_toggle': 'can_content', 'sched_del': 'can_content', 'blocked_del': 'can_manage_settings'}.get(op)
    if not need:
        return None, "Bilinmeyen işlem"
    if not _web_has(chat_id, uid, need):
        return None, "Yetkin yok"
    if op == 'night':
        st, en = _parse_hm(body.get('start')), _parse_hm(body.get('end'))
        if not st or not en:
            return None, "Saat biçimi SS:DD olmalı"
        nm = _nm_data(chat_id)
        want = body.get('restrictions') or {}
        nm['restrictions'] = {k: bool(want.get(k)) for k, _ in NIGHT_RESTRICTIONS}
        (nm['start_hour'], nm['start_minute']), (nm['end_hour'], nm['end_minute']) = st, en
        nm['enabled'] = 1 if body.get('enabled') else 0
        nm['configured'] = 1
        save_nightmod(chat_id, nm)  # kapatılırsa ve şu an aktifse bot 1 dk içinde izinleri geri yükler
        return "🌙 Gece modu kaydedildi", None
    if op == 'note_add':
        name = str(body.get('name') or '').strip().lstrip('#').lower()
        text = source_to_html(str(body.get('text') or '')[:WEB_TEXT_MAX]).strip()
        if not _NOTE_NAME.match(name):
            return None, "Not adı: harf, rakam, - veya _ (en fazla 32)"
        if not text:
            return None, "Not içeriği boş olamaz"
        with get_db() as conn:
            conn.execute("INSERT OR REPLACE INTO notes (chat_id, name, content, file_id, file_type, created_by, created_at) "
                         "VALUES (?, ?, ?, NULL, NULL, ?, ?)", (chat_id, name, text, uid, time.time()))
        return f"📝 #{name} kaydedildi", None
    if op == 'note_del':
        with get_db() as conn:
            n = conn.execute("DELETE FROM notes WHERE chat_id = ? AND name = ?", (chat_id, str(body.get('name')))).rowcount
        return ("🗑 Not silindi", None) if n else (None, "Not bulunamadı")
    if op == 'filter_add':
        parsed = _parse_trigger(str(body.get('trigger') or ''))
        answer = source_to_html(str(body.get('text') or '')[:3500]).strip()
        if not parsed:
            return None, "Tetikleyici geçersiz (en fazla 100 karakter; içinde geçsin diye *kelime*)"
        if not answer:
            return None, "Cevap boş olamaz"
        shown, norm, mode = parsed
        with get_db() as conn:
            exists = conn.execute("SELECT 1 FROM chat_filters WHERE chat_id = ? AND trigger_norm = ?", (chat_id, norm)).fetchone()
            if not exists and conn.execute("SELECT COUNT(*) FROM chat_filters WHERE chat_id = ?",
                                           (chat_id,)).fetchone()[0] >= FILTER_LIMIT:
                return None, f"En fazla {FILTER_LIMIT} filtre olabilir"
            conn.execute("INSERT OR REPLACE INTO chat_filters (chat_id, trigger_norm, trigger_text, mode, reply_text, file_id, "
                         "file_type, created_by, created_at, is_html) VALUES (?, ?, ?, ?, ?, NULL, NULL, ?, ?, 1)",
                         (chat_id, norm, shown, mode, answer, uid, time.time()))
        _filter_changed(chat_id)
        return f"🧩 Filtre {'güncellendi' if exists else 'eklendi'}: {shown}", None
    if op == 'filter_del':
        with get_db() as conn:
            n = conn.execute("DELETE FROM chat_filters WHERE chat_id = ? AND trigger_norm = ?",
                             (chat_id, str(body.get('key')))).rowcount
        _filter_changed(chat_id)
        return ("🗑 Filtre silindi", None) if n else (None, "Filtre bulunamadı")
    if op == 'sched_add':
        try:
            interval = int(body.get('interval'))
        except (TypeError, ValueError):
            interval = None
        if interval not in {i for i, _ in WEB_SCHED_INTERVALS}:
            return None, "Geçersiz aralık"
        err = _sched_check(chat_id, interval)
        if err:
            return None, _strip_html(err)
        rich = build_rich(source_to_html(str(body.get('text') or '')[:WEB_TEXT_MAX]))
        if not rich_plain(rich):
            return None, "Mesaj boş olamaz"
        sched_add(chat_id, rich, interval, uid)
        return "⏰ Zamanlanmış mesaj eklendi", None
    if op in ('sched_toggle', 'sched_del'):
        try:
            sid = int(body.get('id'))
        except (TypeError, ValueError):
            return None, "Geçersiz"
        with get_db() as conn:
            if op == 'sched_del':
                n = conn.execute("DELETE FROM scheduled_msgs WHERE id = ? AND chat_id = ?", (sid, chat_id)).rowcount
            else:
                n = conn.execute("UPDATE scheduled_msgs SET enabled = 1 - enabled WHERE id = ? AND chat_id = ?",
                                 (sid, chat_id)).rowcount
        return ("✅ Güncellendi" if op == 'sched_toggle' else "🗑 Silindi", None) if n else (None, "Bulunamadı")
    if op == 'blocked_del':
        try:
            rid = int(body.get('id'))
        except (TypeError, ValueError):
            return None, "Geçersiz"
        with get_db() as conn:
            n = conn.execute("DELETE FROM blocked_media WHERE rowid = ? AND chat_id = ?", (rid, chat_id)).rowcount
        return ("🗑 Engel kaldırıldı", None) if n else (None, "Bulunamadı")
    return None, "Bilinmeyen işlem"

RTL_LANGS = {'ar', 'fa'}

def web_ui_keys() -> list:
    """Web panel sayfasındaki çevrilecek metinler: L("…") çağrıları ve RICH_HELP."""
    keys = re.findall(r'L\("((?:[^"\\]|\\.)*)"', WEB_PAGE)
    m = re.search(r'const RICH_HELP = "((?:[^"\\]|\\.)*)";', WEB_PAGE)
    return list(dict.fromkeys(keys + ([m.group(1)] if m else [])))

def web_ui(lang: str) -> dict:
    if lang == DEFAULT_LANG or lang not in _I18N_TR:
        return {}
    out = {}
    for k in web_ui_keys():
        t = tr_line(k, lang)
        if t != k:
            out[k] = t
    return out

def _web_translate_payload(p: dict, lang: str) -> dict:
    """Ayar şemasındaki başlık, etiket, açıklama ve seçenek adlarını kişinin diline çevirir (değerler değişmez)."""
    if lang == DEFAULT_LANG or lang not in _I18N_TR:
        return p
    for sec in p.get('sections', []):
        sec['title'] = L(sec['title'], lang)
        for f in sec['fields']:
            f['label'] = L(f['label'], lang)
            if f.get('hint'):
                f['hint'] = L(f['hint'], lang)
            if f.get('options'):
                f['options'] = [[o[0], L(str(o[1]), lang)] for o in f['options']]
            if f.get('type') == 'rich' and isinstance(f.get('value'), dict) and f['value'].get('media'):
                f['value']['media'] = L(f['value']['media'], lang)
    x = p.get('extras')
    if x:
        x['night']['restrictions'] = [[k, L(lbl, lang), on] for k, lbl, on in x['night']['restrictions']]
        for it in x['staff']:
            it['role'] = L(it['role'], lang)
        for it in x['sched']['items']:
            it['every'] = L(it['every'], lang)
        for it in x['blocked']['items']:
            it['label'] = L(it['label'], lang)
        x['sched']['intervals'] = [[v, L(lbl, lang)] for v, lbl in x['sched']['intervals']]
    return p

def web_settings_payload(chat_id: str, uid: int) -> dict:
    s = get_channel_settings(chat_id)['settings']
    sections = []
    for sec in web_schema():
        fields = []
        for f in sec['fields']:
            fields.append({**{k: v for k, v in f.items() if k != 'perm'},
                           'value': _field_value(f['key'], f['type'], s),
                           'editable': _web_has(chat_id, uid, f['perm'])})
        sections.append({'id': sec['id'], 'title': sec['title'], 'fields': fields})
    with get_db() as conn:
        row = conn.execute("SELECT title FROM channels WHERE chat_id = ?", (chat_id,)).fetchone()
    return _web_translate_payload({'chat': chat_id, 'title': (row['title'] if row else None) or chat_id,
                                   'sections': sections, 'fsub_channel': s.get('fsub_title'),
                                   'extras': web_extras(chat_id, uid)}, user_lang(uid))

def web_save(chat_id: str, uid: int, values: dict):
    """Panelden gelen değişiklikleri doğrulayıp kaydeder. Dönüş: (değişen etiketler, hatalar)."""
    channel = get_channel_settings(chat_id)
    s = channel['settings']
    fields = {f['key']: f for sec in web_schema() for f in sec['fields']}
    changed, errors = [], {}
    for key, value in (values or {}).items():
        f = fields.get(key)
        if not f:
            errors[key] = "Bilinmeyen ayar"
            continue
        if not _web_has(chat_id, uid, f['perm']):
            errors[key] = "Yetkin yok"
            continue
        new, err = _validate_field(f, value, s)
        if err:
            errors[key] = err
            continue
        if f['type'] == 'rich':
            kind, rich = new
            if rich is None:
                s['rules'] = ''
                s.pop('rules_rich', None)
            else:
                store_rich(s, kind, rich)
            changed.append(f['label'])
            continue
        if key == 'fsub_enabled' and new and not s.get('fsub_channel'):
            errors[key] = "Önce /kanalzorunlu @kanal ile kanal ayarla"
            continue
        if s.get(key, _default_channel_settings().get(key)) != new:
            s[key] = new
            changed.append(f['label'])
            if key == 'auto_accept' and new:
                s['auto_reject'] = False
    if changed:
        if s.get('banned_words') and 'Yasaklı kelimeler' in changed:
            s['word_ban_enabled'] = True
        save_channel_settings(chat_id, channel)
        with get_db() as conn:
            conn.execute("INSERT OR REPLACE INTO settings_dirty (chat_id, at) VALUES (?, ?)", (chat_id, time.time()))
            conn.commit()
    return changed, errors

async def web_sync_job(context):
    """Web panelden kaydedilen ayarlar: botun önbelleği yenilenir (5 sn içinde etkili olur)."""
    global _web_sync_last
    with get_db() as conn:
        rows = conn.execute("SELECT chat_id, at FROM settings_dirty WHERE at > ?", (_web_sync_last,)).fetchall()
        conn.execute("DELETE FROM settings_dirty WHERE at < ?", (time.time() - 3600,))
        conn.commit()
    global _blocked_media_cache
    for r in rows:
        _invalidate_settings(r['chat_id'])
        _filter_changed(r['chat_id'])
        _web_sync_last = max(_web_sync_last, r['at'])
    if rows:
        _blocked_media_cache = None  # panelden engel kaldırılmış olabilir

def _web_log(token: str, chat_id: str, user: dict, changed: list):
    channel = get_channel_settings(chat_id)
    log_id = channel.get('log_chat_id') if channel else None
    if log_id and changed:
        who = mention_html(user['id'], user.get('first_name') or str(user['id']))
        text = f"🖥 Web panelden değiştirildi: {html.escape(', '.join(changed))[:3000]} | {who}"
        _tg_api(token, 'sendMessage', {'chat_id': log_id, 'parse_mode': 'HTML', 'text': L(text, chat_lang(chat_id))})

def _web_brand(token: str) -> str:
    bid = int(token.split(':')[0])
    with get_db() as conn:
        r = conn.execute("SELECT brand, name FROM clones WHERE bot_id = ?", (bid,)).fetchone()
    return (r['brand'] or r['name'] or 'ULUS') if r and TOKEN and bid != int(TOKEN.split(':')[0]) else 'ULUS'

def web_api(path: str, body: dict):
    """Dönüş: (HTTP durum, JSON sözlüğü)."""
    auth = verify_init_data(body.get('initData') or '')
    if not auth:
        return 401, {'error': "Oturum doğrulanamadı. Paneli Telegram içinden aç."}
    user, token = auth
    uid = user['id']
    if path == 'chats':
        chats = []
        fetched = 0
        for c in _web_bot_chats(token):
            if has_permission(c['chat_id'], uid, 50):
                title = c['title']
                if (not title or title == c['chat_id']) and fetched < 25:  # eski kayıt: adı Telegram'dan alınır, kaydedilir
                    fetched += 1
                    info = _tg_api(token, 'getChat', {'chat_id': c['chat_id']})
                    title = (info or {}).get('title') or title
                    if title and title != c['chat_id']:
                        with get_db() as conn:
                            conn.execute("UPDATE channels SET title = ? WHERE chat_id = ?", (title, c['chat_id']))
                chats.append({'id': c['chat_id'], 'title': title or c['chat_id']})
        ul = user_lang(uid)
        return 200, {'user': user.get('first_name') or '', 'brand': _web_brand(token), 'chats': chats, 'lang': ul,
                     'rtl': ul in RTL_LANGS, 'ui': web_ui(ul), 'langs': [[k, v] for k, v in available_langs().items()]}
    if path == 'setlang':
        lang = str(body.get('lang') or '')
        if lang not in available_langs():
            return 400, {'error': "Geçersiz dil"}
        set_user_lang(uid, lang)
        return 200, {'ok': True}
    ul = user_lang(uid)
    chat_id = str(body.get('chat') or '')
    if not re.fullmatch(r'-\d{5,20}', chat_id) or not get_channel_settings(chat_id):
        return 404, {'error': L("Grup bulunamadı", ul)}
    if not _web_chat_allowed(token, chat_id, uid):
        return 403, {'error': L("Bu grupta yönetici değilsin (ya da bot Telegram'a ulaşamadı).", ul)}
    if path == 'settings':
        return 200, web_settings_payload(chat_id, uid)
    if path == 'save':
        if maintenance_on():
            return 503, {'error': L("Bot bakımda, biraz sonra tekrar dene.", ul)}
        changed, errors = web_save(chat_id, uid, body.get('values') or {})
        if changed:
            _web_log(token, chat_id, user, changed)
        return 200, {'changed': [L(c, ul) for c in changed], 'errors': {k: L(v, ul) for k, v in errors.items()},
                     'settings': web_settings_payload(chat_id, uid)}
    if path == 'op':
        if maintenance_on():
            return 503, {'error': L("Bot bakımda, biraz sonra tekrar dene.", ul)}
        msg, err = web_op(chat_id, uid, body)
        if msg:
            with get_db() as conn:
                conn.execute("INSERT OR REPLACE INTO settings_dirty (chat_id, at) VALUES (?, ?)", (chat_id, time.time()))
            _web_log(token, chat_id, user, [msg])
        extras = _web_translate_payload({'extras': web_extras(chat_id, uid)}, ul)['extras']
        return 200, {'ok': L(msg, ul) if msg else msg, 'error': L(err, ul) if err else err, 'extras': extras}
    return 404, {'error': "Bilinmeyen işlem"}

def webapp(environ, start_response):
    """WSGI uygulaması: / → panel sayfası, POST …/api/<işlem> → JSON."""
    path = environ.get('PATH_INFO') or '/'
    method = environ.get('REQUEST_METHOD', 'GET')

    def reply(status: int, body, ctype: str = 'application/json; charset=utf-8'):
        data = body if isinstance(body, bytes) else (json.dumps(body, ensure_ascii=False).encode()
                                                      if not isinstance(body, str) else body.encode())
        reason = {200: 'OK', 400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found',
                  405: 'Method Not Allowed', 413: 'Payload Too Large', 500: 'Internal Server Error'}.get(status, 'OK')
        start_response(f"{status} {reason}", [('Content-Type', ctype), ('Content-Length', str(len(data))),
                                              ('Cache-Control', 'no-store'), ('X-Content-Type-Options', 'nosniff')])
        return [data]
    try:
        if '/api/' in path:
            if method != 'POST':
                return reply(405, {'error': "POST gerekli"})
            try:
                size = int(environ.get('CONTENT_LENGTH') or 0)
            except ValueError:
                size = 0
            if size > WEB_MAX_BODY:
                return reply(413, {'error': "İstek çok büyük"})
            try:
                body = json.loads(environ['wsgi.input'].read(size).decode() or '{}')
            except (ValueError, UnicodeDecodeError):
                return reply(400, {'error': "Geçersiz istek"})
            if not isinstance(body, dict):
                return reply(400, {'error': "Geçersiz istek"})
            status, data = web_api(path.rsplit('/api/', 1)[1].strip('/'), body)
            return reply(status, data)
        rm = re.search(r'/r/(\d+)/(\d+)/(\d+)/([0-9a-f]{12})/?$', path)
        if rm and method == 'GET':  # duyuru butonu: tıklamayı say, asıl adrese yönlendir
            target = duyuru_click(int(rm.group(1)), int(rm.group(2)), int(rm.group(3)), rm.group(4))
            if not target:
                return reply(404, "Bağlantı geçersiz", 'text/plain; charset=utf-8')
            start_response("302 Found", [('Location', target), ('Content-Length', '0'), ('Cache-Control', 'no-store')])
            return [b'']
        if path.rstrip('/').endswith('/health'):
            return reply(200, "ok", 'text/plain; charset=utf-8')
        if method == 'GET':
            return reply(200, WEB_PAGE, 'text/html; charset=utf-8')
        return reply(405, {'error': "Desteklenmeyen istek"})
    except Exception as e:
        logger.exception(f"Web panel hatası: {e}")
        return reply(500, {'error': "Sunucu hatası"})

# ── Bot tarafı: paneli açan butonlar ──
def webpanel_markup(chat_id: str | None = None) -> InlineKeyboardMarkup | None:
    if not WEBAPP_URL:
        return None
    url = WEBAPP_URL + (("&" if "?" in WEBAPP_URL else "?") + f"chat={chat_id}" if chat_id else "")
    return InlineKeyboardMarkup([[InlineKeyboardButton("🖥 Web paneli aç", web_app=WebAppInfo(url))]])

async def cmd_webpanel(update: Update, context):
    """/webpanel — ayarları Telegram içinde açılan web sayfasından yönet (Mini App)."""
    msg = update.effective_message
    if not WEBAPP_URL:
        await msg.reply_text("Web panel bu botta açılmamış (.env içinde WEBAPP_URL boş).")
        return
    if update.effective_chat.type != 'private':
        await msg.reply_text("🖥 Web panel bota özelden açılır:", reply_markup=InlineKeyboardMarkup(
            [[InlineKeyboardButton("🖥 Özelden aç", url=f"https://t.me/{context.bot.username}?start=webpanel")]]))
        return
    await msg.reply_text("🖥 <b>Web panel</b>\nTüm ayarlar tek sayfada: korumalar, düzenleme koruması, uygunsuz medya, "
                         "katılım, karşılama, listeler, gece modu, notlar, filtreler, zamanlanmış mesajlar, engelli medya, "
                         "yetkililer ve grup istatistikleri. Değişiklikler birkaç saniye içinde bota yansır.",
                         parse_mode=ParseMode.HTML, reply_markup=webpanel_markup(context.user_data.get('selected_channel')))

# Panel sayfası (tek dosya: HTML + JS; Telegram'ın tema renklerini kullanır)
WEB_PAGE = r'''<!doctype html>
<html lang="tr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Panel</title>
<script src="https://telegram.org/js/telegram-web-app.js"></script>
<style>
:root {
  --bg: var(--tg-theme-secondary-bg-color, #f1f1f4);
  --card: var(--tg-theme-section-bg-color, var(--tg-theme-bg-color, #ffffff));
  --text: var(--tg-theme-text-color, #111111);
  --hint: var(--tg-theme-hint-color, #8a8a8e);
  --accent: var(--tg-theme-button-color, #2a78d6);
  --accent-text: var(--tg-theme-button-text-color, #ffffff);
  --head: var(--tg-theme-section-header-text-color, var(--tg-theme-hint-color, #6d6d72));
  --danger: var(--tg-theme-destructive-text-color, #d93c3c);
  --line: color-mix(in srgb, var(--hint) 22%, transparent);
}
* { box-sizing: border-box; }
html, body { margin: 0; background: var(--bg); color: var(--text);
  font: 15px/1.4 -apple-system, system-ui, "Segoe UI", Roboto, sans-serif; -webkit-font-smoothing: antialiased; }
main { max-width: 640px; margin: 0 auto; padding: 12px 16px 96px; }
header { padding: 8px 2px 12px; }
h1 { font-size: 20px; margin: 0 0 2px; }
.sub { color: var(--hint); font-size: 13px; }
.picker { width: 100%; margin-top: 10px; padding: 11px 12px; border-radius: 12px; border: 1px solid var(--line);
  background: var(--card); color: var(--text); font-size: 15px; }
details.sec { background: var(--card); border-radius: 14px; margin: 12px 0; overflow: hidden; }
details.sec > summary { list-style: none; cursor: pointer; padding: 13px 14px; font-weight: 600; display: flex;
  align-items: center; justify-content: space-between; }
details.sec > summary::-webkit-details-marker { display: none; }
details.sec > summary::after { content: "›"; color: var(--hint); font-size: 20px; transition: transform .15s; }
details.sec[open] > summary::after { transform: rotate(90deg); }
.row { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 11px 14px;
  border-top: 1px solid var(--line); }
.row.col { flex-direction: column; align-items: stretch; }
.lbl { flex: 1; min-width: 0; }
.hint { color: var(--hint); font-size: 12.5px; margin-top: 2px; }
.ro { opacity: .55; }
select, textarea { font: inherit; color: var(--text); background: var(--bg); border: 1px solid var(--line);
  border-radius: 10px; padding: 8px 10px; }
select { max-width: 52%; }
textarea { width: 100%; min-height: 110px; resize: vertical; margin-top: 8px; font-size: 14px; }
.sw { position: relative; width: 50px; height: 30px; flex: none; }
.sw input { opacity: 0; width: 0; height: 0; position: absolute; }
.sw span { position: absolute; inset: 0; border-radius: 30px; background: var(--line); transition: background .15s; }
.sw span::before { content: ""; position: absolute; width: 26px; height: 26px; left: 2px; top: 2px; border-radius: 50%;
  background: #fff; box-shadow: 0 1px 3px rgba(0,0,0,.25); transition: transform .15s; }
.sw input:checked + span { background: var(--accent); }
.sw input:checked + span::before { transform: translateX(20px); }
.sw input:focus-visible + span { outline: 2px solid var(--accent); outline-offset: 2px; }
.media { display: flex; gap: 8px; align-items: center; margin-top: 6px; font-size: 13px; color: var(--hint); }
.err { color: var(--danger); font-size: 12.5px; margin-top: 4px; }
.changed { box-shadow: inset 3px 0 0 var(--accent); }
.save { position: fixed; left: 16px; right: 16px; bottom: 16px; max-width: 608px; margin: 0 auto; padding: 14px;
  border: 0; border-radius: 12px; background: var(--accent); color: var(--accent-text); font-size: 16px;
  font-weight: 600; display: none; }
.toast { position: fixed; left: 50%; top: 14px; transform: translateX(-50%); background: var(--text); color: var(--card);
  padding: 9px 14px; border-radius: 10px; font-size: 14px; opacity: 0; transition: opacity .2s; pointer-events: none;
  max-width: 90vw; }
.toast.on { opacity: .92; }
.empty { text-align: center; color: var(--hint); padding: 40px 10px; }
.help { color: var(--hint); font-size: 12.5px; padding: 0 14px 12px; }
code { font-size: 12px; }
.stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(96px, 1fr)); gap: 8px; margin: 4px 0 12px; }
.stat { background: var(--card); border-radius: 12px; padding: 10px 12px; }
.stat b { display: block; font-size: 19px; }
.stat span { color: var(--hint); font-size: 12px; }
.item { display: flex; align-items: center; gap: 10px; padding: 10px 14px; border-top: 1px solid var(--line); }
.item .lbl div:first-child { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.btn { font: inherit; font-size: 14px; border: 0; border-radius: 10px; padding: 8px 12px; background: var(--accent);
  color: var(--accent-text); cursor: pointer; flex: none; }
.btn.ghost { background: transparent; color: var(--danger); padding: 6px 8px; font-size: 17px; }
.btn:disabled { opacity: .5; }
.form { padding: 10px 14px 14px; border-top: 1px solid var(--line); display: flex; flex-direction: column; gap: 8px; }
.form textarea { margin-top: 0; min-height: 80px; }
input[type=text], input[type=time] { font: inherit; color: var(--text); background: var(--bg); border: 1px solid var(--line);
  border-radius: 10px; padding: 8px 10px; }
.chips { display: flex; flex-wrap: wrap; gap: 8px; padding: 10px 14px; border-top: 1px solid var(--line); }
.chip { display: flex; align-items: center; gap: 6px; background: var(--bg); border-radius: 18px; padding: 6px 10px; font-size: 14px; }
.badge { font-size: 12px; color: var(--hint); }
</style>
</head>
<body>
<main>
  <header>
    <h1 id="title">⚙️ Panel</h1>
    <div class="sub" id="sub">Yükleniyor…</div>
    <select class="picker" id="picker" hidden aria-label="Grup seç"></select>
    <select class="picker" id="langPick" hidden aria-label="Language"></select>
  </header>
  <div id="stats"></div>
  <div id="content"></div>
  <div id="extras"></div>
</main>
<button class="save" id="saveBtn" type="button">Kaydet</button>
<div class="toast" id="toast" role="status"></div>
<script>
"use strict";
const tg = window.Telegram && window.Telegram.WebApp;
const initData = tg ? tg.initData : "";
const base = location.pathname.replace(/\/+$/, "") + "/";
const $ = (id) => document.getElementById(id);
let state = { chat: null, fields: {}, changes: {} };
const UI = {};
function L(s) {  // çeviri: sunucu kişinin dilindeki karşılıkları gönderir; ⟨0⟩ ⟨1⟩ değişken yerleri
  const args = Array.prototype.slice.call(arguments, 1);
  return (UI[s] || s).replace(/⟨(\d+)⟩/g, (m, i) => (args[+i] !== undefined ? String(args[+i]) : m));
}

if (tg) { tg.ready(); tg.expand(); }

function toast(text) {
  const t = $("toast"); t.textContent = text; t.classList.add("on");
  clearTimeout(t._h); t._h = setTimeout(() => t.classList.remove("on"), 2600);
}

async function api(path, extra) {
  const r = await fetch(base + "api/" + path, { method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify(Object.assign({ initData: initData }, extra || {})) });
  let data = {};
  try { data = await r.json(); } catch (e) { data = { error: L("Sunucuya ulaşılamadı") }; }
  if (!r.ok) throw new Error(data.error || L("Hata ⟨0⟩", r.status));
  return data;
}

function el(tag, attrs, children) {
  const e = document.createElement(tag);
  for (const k in (attrs || {})) {
    if (k === "text") e.textContent = attrs[k];
    else if (k === "cls") e.className = attrs[k];
    else e.setAttribute(k, attrs[k]);
  }
  (children || []).forEach((c) => c && e.appendChild(c));
  return e;
}

function setDirty() {
  const n = Object.keys(state.changes).length;
  const label = n ? L("Kaydet (⟨0⟩)", n) : L("Kaydet");
  if (tg && tg.MainButton) {
    tg.MainButton.setText(label);
    n ? tg.MainButton.show() : tg.MainButton.hide();
  } else {
    $("saveBtn").textContent = label;
    $("saveBtn").style.display = n ? "block" : "none";
  }
}

function track(f, row, value) {
  state.changes[f.key] = value;
  row.classList.add("changed");
  setDirty();
}

function fieldRow(f) {
  const lbl = el("div", { cls: "lbl" }, [el("div", { text: f.label }), f.hint ? el("div", { cls: "hint", text: f.hint }) : null]);
  if (f.type === "bool") {
    const row = el("label", { cls: "row" + (f.editable ? "" : " ro") });
    const input = el("input", { type: "checkbox", role: "switch", "aria-label": f.label });
    input.checked = !!f.value; input.disabled = !f.editable;
    input.addEventListener("change", () => { track(f, row, input.checked); if (tg && tg.HapticFeedback) tg.HapticFeedback.selectionChanged(); });
    row.append(lbl, el("span", { cls: "sw" }, [input, el("span")]));
    return row;
  }
  if (f.type === "select") {
    const row = el("div", { cls: "row" + (f.editable ? "" : " ro") });
    const sel = el("select", { "aria-label": f.label });
    f.options.forEach((o) => { const op = el("option", { value: String(o[0]), text: o[1] }); if (String(o[0]) === String(f.value)) op.selected = true; sel.appendChild(op); });
    sel.disabled = !f.editable;
    sel.addEventListener("change", () => track(f, row, sel.value));
    row.append(lbl, sel);
    return row;
  }
  const row = el("div", { cls: "row col" + (f.editable ? "" : " ro") });
  const ta = el("textarea", { "aria-label": f.label, spellcheck: "false" });
  ta.disabled = !f.editable;
  row.appendChild(lbl);
  if (f.type === "list") {
    ta.value = f.value || "";
    ta.addEventListener("input", () => track(f, row, ta.value));
    row.appendChild(ta);
    return row;
  }
  // rich: metin + butonlar + %%% ; medya bot üzerinden değiştirilir
  const v = f.value || {};
  ta.value = v.text || "";
  let removeMedia = false;
  const send = () => track(f, row, { text: ta.value, remove_media: removeMedia });
  ta.addEventListener("input", send);
  row.appendChild(ta);
  if (v.media) {
    const cb = el("input", { type: "checkbox" }); cb.disabled = !f.editable;
    cb.addEventListener("change", () => { removeMedia = cb.checked; send(); });
    row.appendChild(el("label", { cls: "media" }, [cb, el("span", { text: L("🖼 ⟨0⟩ ekli — kaldırmak için işaretle", v.media) })]));
  }
  return row;
}

const RICH_HELP = "Butonlar: her satıra  Etiket - https://link  (yan yana: &&) · Kurallar - rules · Bilgi - popup:metin · Değişkenler: {kullanıcı} {ad} {grup} {uye_sayisi} · Rastgele mesaj: araya tek başına %%% satırı · Kalın/italik için <b> <i> etiketleri. Medyayı bota /setwelcome ile ekle.";

function render(data) {
  state.fields = {}; state.changes = {}; setDirty();
  $("title").textContent = "⚙️ " + data.title;
  const c = $("content"); c.innerHTML = "";
  data.sections.forEach((sec, i) => {
    const d = el("details", { cls: "sec" }); if (i === 0) d.open = true;
    d.appendChild(el("summary", { text: sec.title }));
    sec.fields.forEach((f) => { state.fields[f.key] = f; d.appendChild(fieldRow(f)); });
    if (sec.id === "welcome") d.appendChild(el("div", { cls: "help", text: L(RICH_HELP) }));
    if (sec.id === "tag" && data.fsub_channel) d.appendChild(el("div", { cls: "help", text: L("Zorunlu kanal: ⟨0⟩", data.fsub_channel) }));
    c.appendChild(d);
  });
  if (data.extras) renderExtras(data.extras);
}

function ask(text) {
  return new Promise((res) => {
    if (tg && tg.showConfirm) { try { tg.showConfirm(text, (ok) => res(!!ok)); return; } catch (e) {} }
    res(window.confirm(text));
  });
}

async function op(payload, okText) {
  try {
    const r = await api("op", Object.assign({ chat: state.chat }, payload));
    if (r.extras) renderExtras(r.extras);
    toast(r.error ? "⚠️ " + r.error : (r.ok || okText || L("✅ Tamam")));
    if (tg && tg.HapticFeedback) tg.HapticFeedback.notificationOccurred(r.error ? "warning" : "success");
    return !r.error;
  } catch (e) { toast("❌ " + e.message); return false; }
}

function sec(title, open) {
  const d = el("details", { cls: "sec" }); if (open) d.open = true;
  d.appendChild(el("summary", { text: title }));
  return d;
}

function itemRow(main, sub, actions) {
  const r = el("div", { cls: "item" });
  r.appendChild(el("div", { cls: "lbl" }, [el("div", { text: main }), sub ? el("div", { cls: "hint", text: sub }) : null]));
  (actions || []).forEach((a) => a && r.appendChild(a));
  return r;
}

function delBtn(label, payload, editable) {
  const b = el("button", { cls: "btn ghost", type: "button", "aria-label": L("Sil"), text: "🗑" });
  b.disabled = !editable;
  b.addEventListener("click", async () => { if (await ask(L("⟨0⟩ silinsin mi?", label))) op(payload); });
  return b;
}

function switchEl(checked, disabled, onChange, label) {
  const input = el("input", { type: "checkbox", role: "switch", "aria-label": label || L("Aç/kapat") });
  input.checked = !!checked; input.disabled = !!disabled;
  input.addEventListener("change", () => onChange(input.checked, input));
  return el("label", { cls: "sw" }, [input, el("span")]);
}

function renderStats(x) {
  const box = $("stats"); box.innerHTML = "";
  const st = x.stats || {};
  const tiles = [[L("Mesaj (7 gün)"), st.msgs], [L("Aktif kişi"), st.active], [L("Katılan (7 gün)"), st.joins],
                 [L("Uyarılı"), st.warns], [L("Banlı"), st.bans]];
  const g = el("div", { cls: "stats" });
  tiles.forEach(([k, v]) => g.appendChild(el("div", { cls: "stat" }, [el("b", { text: String(v || 0) }), el("span", { text: k })])));
  box.appendChild(g);
  box.appendChild(el("div", { cls: "sub", text: L("📋 Log kanalı: ⟨0⟩", x.log || L("ayarlı değil (botta /setlog)")) }));
}

function renderExtras(x) {
  renderStats(x);
  const c = $("extras"); c.innerHTML = "";
  // 🌙 Gece modu
  const n = x.night, nd = sec(L("🌙 Gece modu") + (n.enabled ? (n.active ? L(" · şu an aktif") : L(" · açık")) : ""));
  let nEnabled = n.enabled;
  nd.appendChild(el("label", { cls: "row" + (n.editable ? "" : " ro") }, [
    el("div", { cls: "lbl" }, [el("div", { text: L("Gece modu") }), el("div", { cls: "hint", text: L("Seçili izinler bu saatlerde kapanır, bitince eski izinler geri gelir (UTC+3).") })]),
    switchEl(n.enabled, !n.editable, (v) => { nEnabled = v; }, L("Gece modu"))]));
  const st = el("input", { type: "time", value: n.start, "aria-label": L("Başlangıç") }), en = el("input", { type: "time", value: n.end, "aria-label": L("Bitiş") });
  st.disabled = en.disabled = !n.editable;
  nd.appendChild(el("div", { cls: "row" }, [el("div", { cls: "lbl", text: L("Başlangıç") }), st]));
  nd.appendChild(el("div", { cls: "row" }, [el("div", { cls: "lbl", text: L("Bitiş") }), en]));
  const chips = el("div", { cls: "chips" }), want = {};
  n.restrictions.forEach(([k, lbl, on]) => {
    want[k] = on;
    const cb = el("input", { type: "checkbox" }); cb.checked = on; cb.disabled = !n.editable;
    cb.addEventListener("change", () => { want[k] = cb.checked; });
    chips.appendChild(el("label", { cls: "chip" }, [cb, el("span", { text: "🚫 " + lbl })]));
  });
  nd.appendChild(el("div", { cls: "help", text: L("Kapatılacaklar:") }));
  nd.appendChild(chips);
  const nb = el("button", { cls: "btn", type: "button", text: L("Gece modunu kaydet") }); nb.disabled = !n.editable;
  nb.addEventListener("click", () => op({ op: "night", enabled: nEnabled, start: st.value, end: en.value, restrictions: want }));
  nd.appendChild(el("div", { cls: "form" }, [nb]));
  c.appendChild(nd);
  // 📝 Notlar
  const no = x.notes, nod = sec(L("📝 Notlar (⟨0⟩)", no.items.length));
  no.items.forEach((it) => nod.appendChild(itemRow("#" + it.name, it.preview, [delBtn("#" + it.name, { op: "note_del", name: it.name }, no.editable)])));
  if (!no.items.length) nod.appendChild(el("div", { cls: "help", text: L("Henüz not yok. Üyeler #isim yazınca not gönderilir.") }));
  if (no.editable) {
    const nm = el("input", { type: "text", placeholder: L("Not adı (örn. kurallar)"), maxlength: "32" });
    const tx = el("textarea", { placeholder: L("Not içeriği (biçim: <b>kalın</b>, butonlar: Etiket - https://link)") });
    const b = el("button", { cls: "btn", type: "button", text: L("➕ Not ekle") });
    b.addEventListener("click", async () => { if (await op({ op: "note_add", name: nm.value, text: tx.value })) { nm.value = ""; tx.value = ""; } });
    nod.appendChild(el("div", { cls: "form" }, [nm, tx, b]));
  }
  c.appendChild(nod);
  // 🧩 Filtreler
  const fl = x.filters, fd = sec(L("🧩 Filtreler / otomatik yanıt (⟨0⟩/⟨1⟩)", fl.items.length, fl.limit));
  fl.items.forEach((it) => fd.appendChild(itemRow((it.contains ? L("💬 içinde: ⟨0⟩", it.trigger) : "💬 " + it.trigger), it.preview,
    [delBtn(it.trigger, { op: "filter_del", key: it.key }, fl.editable)])));
  if (!fl.items.length) fd.appendChild(el("div", { cls: "help", text: L("Henüz filtre yok.") }));
  if (fl.editable) {
    const tr = el("input", { type: "text", placeholder: L("Tetikleyici (içinde geçsin: *kelime*)"), maxlength: "100" });
    const tx = el("textarea", { placeholder: L("Cevap ({kullanıcı} {ad} {grup} değişkenleri, buton satırları)") });
    const b = el("button", { cls: "btn", type: "button", text: L("➕ Filtre ekle") });
    b.addEventListener("click", async () => { if (await op({ op: "filter_add", trigger: tr.value, text: tx.value })) { tr.value = ""; tx.value = ""; } });
    fd.appendChild(el("div", { cls: "form" }, [tr, tx, b]));
    fd.appendChild(el("div", { cls: "help", text: L("Medyalı (sticker/foto) cevap için grupta medyaya yanıt verip /filter kullan.") }));
  }
  c.appendChild(fd);
  // ⏰ Zamanlanmış mesajlar
  const sc = x.sched, sd = sec(L("⏰ Zamanlanmış mesajlar (⟨0⟩)", sc.items.length));
  sc.items.forEach((it) => sd.appendChild(itemRow(it.preview, L("Her ⟨0⟩ · sıradaki: ⟨1⟩", it.every, it.next),
    [switchEl(it.enabled, !sc.editable, () => op({ op: "sched_toggle", id: it.id }), L("Açık/kapalı")),
     delBtn(L("Bu zamanlanmış mesaj"), { op: "sched_del", id: it.id }, sc.editable)])));
  if (!sc.items.length) sd.appendChild(el("div", { cls: "help", text: L("Henüz zamanlanmış mesaj yok.") }));
  if (sc.editable) {
    const tx = el("textarea", { placeholder: L("Mesaj (buton satırları ve %%% ile rastgele seçenek desteklenir)") });
    const iv = el("select", { "aria-label": L("Aralık") });
    sc.intervals.forEach(([v, l]) => iv.appendChild(el("option", { value: String(v), text: l })));
    iv.value = "21600";
    const b = el("button", { cls: "btn", type: "button", text: L("➕ Zamanlanmış mesaj ekle") });
    b.addEventListener("click", async () => { if (await op({ op: "sched_add", text: tx.value, interval: iv.value })) tx.value = ""; });
    sd.appendChild(el("div", { cls: "form" }, [tx, iv, b]));
  }
  c.appendChild(sd);
  // 🚫 Engelli medya
  const bm = x.blocked, bd = sec(L("🚫 Engelli medya (⟨0⟩)", bm.items.length));
  bm.items.forEach((it) => bd.appendChild(itemRow(it.label, null, [delBtn(L("Bu engel"), { op: "blocked_del", id: it.id }, bm.editable)])));
  bd.appendChild(el("div", { cls: "help", text: L("Eklemek için grupta medyaya yanıt verip /medyaengel, sticker paketi için /paketengel yaz.") }));
  c.appendChild(bd);
  // 👮 Yetkililer
  const sf = sec(L("👮 Yetkililer (⟨0⟩)", x.staff.length));
  x.staff.forEach((p) => sf.appendChild(itemRow(p.name, p.role + " · " + p.id)));
  sf.appendChild(el("div", { cls: "help", text: L("Rütbe vermek/almak için grupta /admin, /basadmin, /yardimcikurucu; kişiye özel yetkiler için botta /yetkiler.") }));
  c.appendChild(sf);
}

async function loadChat(chat) {
  state.chat = chat;
  $("content").innerHTML = ""; $("extras").innerHTML = ""; $("stats").innerHTML = "";
  $("content").appendChild(el("div", { cls: "empty", text: L("Yükleniyor…") }));
  try { render(await api("settings", { chat: chat })); }
  catch (e) { $("content").innerHTML = ""; $("content").appendChild(el("div", { cls: "empty", text: e.message })); }
}

async function save() {
  if (!Object.keys(state.changes).length) return;
  if (tg && tg.MainButton) tg.MainButton.showProgress();
  try {
    const res = await api("save", { chat: state.chat, values: state.changes });
    const errs = Object.entries(res.errors || {});
    render(res.settings);
    if (errs.length) toast("⚠️ " + errs.map(([k, v]) => ((state.fields[k] || {}).label || k) + ": " + v).join(" · "));
    else toast(res.changed.length ? L("✅ Kaydedildi") : L("Değişiklik yok"));
    if (tg && tg.HapticFeedback) tg.HapticFeedback.notificationOccurred(errs.length ? "warning" : "success");
  } catch (e) { toast("❌ " + e.message); }
  finally { if (tg && tg.MainButton) tg.MainButton.hideProgress(); }
}

async function start() {
  if (!initData) { $("sub").textContent = "Bu sayfa Telegram içinden açılmalı (botta /webpanel). / Open this page inside Telegram (/webpanel)."; return; }
  if (tg && tg.MainButton) tg.MainButton.onClick(save); else $("saveBtn").addEventListener("click", save);
  try {
    const d = await api("chats");
    Object.assign(UI, d.ui || {});
    document.documentElement.lang = d.lang || "tr";
    document.documentElement.dir = d.rtl ? "rtl" : "ltr";
    const lp = $("langPick"); lp.hidden = false;
    (d.langs || []).forEach(([code, label]) => { const o = el("option", { value: code, text: label }); if (code === d.lang) o.selected = true; lp.appendChild(o); });
    lp.addEventListener("change", async () => { try { await api("setlang", { lang: lp.value }); location.reload(); } catch (e) { toast("❌ " + e.message); } });
    document.title = d.brand + " Panel";
    $("sub").textContent = d.brand + " · " + (d.chats.length ? L("Yönettiğin gruplar") : L("Yönettiğin grup yok"));
    if (!d.chats.length) { $("content").appendChild(el("div", { cls: "empty", text: L("Botun yönetici olduğu ve senin yetkili olduğun bir grup bulunamadı.") })); return; }
    const p = $("picker"); p.hidden = d.chats.length < 2;
    d.chats.forEach((c) => p.appendChild(el("option", { value: c.id, text: c.title })));
    const want = new URLSearchParams(location.search).get("chat") || (tg && tg.initDataUnsafe && tg.initDataUnsafe.start_param) || "";
    const first = d.chats.some((c) => c.id === want) ? want : d.chats[0].id;
    p.value = first;
    p.addEventListener("change", () => {
      if (Object.keys(state.changes).length && !confirm(L("Kaydedilmemiş değişiklikler silinsin mi?"))) { p.value = state.chat; return; }
      loadChat(p.value);
    });
    loadChat(first);
  } catch (e) { $("sub").textContent = e.message; }
}
start();
</script>
</body>
</html>
'''


# ═══════════════════════════ PERFORMANS: ölçüm (/perf) + toplu yazma ═══════════════════════════
# Her handler'ın süresi ölçülür; mesaj sayacı ve üye kaydı bellekte biriktirilip 2 sn'de bir tek seferde yazılır.
PERF: dict = {'handlers': {}, 'since': time.time(), 'updates': 0, 'flushes': 0, 'flushed_rows': 0, 'lag': []}
WRITE_FLUSH_EVERY = 2      # sn
WRITE_FLUSH_MAX = 300      # bu kadar satır birikince beklemeden yazılır
_stats_buf: list = []      # message_stats satırları
_users_buf: dict = {}      # (user_id, chat_id) -> users satırı
_cache_buf: dict = {}      # (chat_id, message_id) -> msg_cache satırı

def perf_wrap(fn):
    """Handler süresini ölçer (çağrı sayısı, toplam, en uzun). Testlerin/yönlendirmenin gördüğü asıl fonksiyon korunur."""
    inner = getattr(fn, '__wrapped__', fn)
    name = getattr(inner, '__name__', 'handler')

    @functools.wraps(fn)
    async def wrapper(update, context):
        t = time.perf_counter()
        try:
            return await fn(update, context)
        finally:
            dt = time.perf_counter() - t
            st = PERF['handlers'].get(name)
            if st is None:
                st = PERF['handlers'][name] = [0, 0.0, 0.0]
            st[0] += 1
            st[1] += dt
            if dt > st[2]:
                st[2] = dt
    wrapper.__wrapped__ = inner
    return wrapper

def queue_user(chat_id: str, user):
    """upsert_user'ın toplu yazılan hâli (her grup mesajında çağrılır)."""
    now = time.time()
    _users_buf[(user.id, chat_id)] = (user.id, chat_id, user.username or '', user.first_name or '',
                                      getattr(user, 'last_name', '') or '', int(user.is_bot), now, now)
    if len(_users_buf) >= WRITE_FLUSH_MAX:
        flush_writes()

def queue_message_stat(chat_id: str, user, msg_type: str):
    _stats_buf.append((chat_id, user.id, user.username or '', user.first_name or '', msg_type, time.time()))
    if len(_stats_buf) >= WRITE_FLUSH_MAX:
        flush_writes()

def flush_writes():
    """Biriken mesaj sayacı ve üye kayıtlarını tek işlemde yazar. Bu tablolardan okuyan kod önce bunu çağırır."""
    if not _stats_buf and not _users_buf and not _cache_buf:
        return
    stats, users, cache = _stats_buf[:], list(_users_buf.values()), list(_cache_buf.values())
    _stats_buf.clear()
    _users_buf.clear()
    _cache_buf.clear()
    try:
        with get_db() as conn:
            if users:
                conn.executemany("""
                    INSERT INTO users (user_id, chat_id, username, first_name, last_name, is_bot, joined_at, last_seen)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                    ON CONFLICT(user_id, chat_id) DO UPDATE SET
                        username = excluded.username, first_name = excluded.first_name,
                        last_name = excluded.last_name, last_seen = excluded.last_seen, left_at = NULL""", users)
            if stats:
                conn.executemany("INSERT INTO message_stats (chat_id, user_id, username, first_name, msg_type, sent_at) "
                                 "VALUES (?, ?, ?, ?, ?, ?)", stats)
            if cache:
                conn.executemany("INSERT OR IGNORE INTO msg_cache (chat_id, message_id, user_id, text, sent_at) "
                                 "VALUES (?, ?, ?, ?, ?)", cache)
    except sqlite3.Error as e:
        logger.error(f"Toplu yazma başarısız ({len(stats)} mesaj, {len(users)} üye): {e}")
        _stats_buf[:0] = stats  # kaybolmasın: bir sonraki turda tekrar denenir
        for u in users:
            _users_buf.setdefault((u[0], u[1]), u)
        for c in cache:
            _cache_buf.setdefault((c[0], c[1]), c)
        return
    PERF['flushes'] += 1
    PERF['flushed_rows'] += len(stats) + len(users) + len(cache)

async def flush_writes_job(context):
    flush_writes()

async def loop_lag_job(context):
    """Olay döngüsü gecikmesi: bir işlem döngüyü bloke ederse burada görünür."""
    loop = asyncio.get_running_loop()
    t = loop.time()
    await asyncio.sleep(0.05)
    lag = max(0.0, loop.time() - t - 0.05)
    PERF['lag'] = (PERF['lag'] + [lag])[-60:]

def _proc_mem() -> tuple:
    """(şu anki, en yüksek) bellek MB"""
    cur = peak = None
    try:
        with open('/proc/self/status') as f:
            for line in f:
                if line.startswith('VmRSS:'):
                    cur = int(line.split()[1]) / 1024
                elif line.startswith('VmHWM:'):
                    peak = int(line.split()[1]) / 1024
    except OSError:
        pass
    return cur, peak

def _fmt_ms(sec: float) -> str:
    return f"{sec * 1000:.0f} ms" if sec < 1 else f"{sec:.1f} sn"

def perf_report(app=None) -> str:
    up = int(time.time() - PERF['since'])
    cur, peak = _proc_mem()
    db_mb = sum(os.path.getsize(p) for p in (DB_FILE, DB_FILE + '-wal') if os.path.exists(p)) / 1048576
    with get_db() as conn:
        n_groups = conn.execute("SELECT COUNT(*) FROM channels WHERE chat_type IN ('group','supergroup')").fetchone()[0]
        n_channels = conn.execute("SELECT COUNT(*) FROM channels WHERE chat_type = 'channel'").fetchone()[0]
    queues = []
    for label, a in [("ana", app)] + [(f"@{(CLONES.get(b) or {}).get('username') or b}", a2) for b, a2 in CLONE_APPS.items()]:
        if a is None:
            continue
        q = getattr(getattr(a, 'update_queue', None), 'qsize', lambda: 0)()
        busy = getattr(getattr(a, 'update_processor', None), 'current_concurrent_updates', None)
        queues.append(f"{label}: {q} bekleyen" + (f", {busy} işleniyor" if busy is not None else ""))
    lag = PERF['lag']
    lines = [f"⚡ <b>Performans</b> — çalışma süresi {human_duration(up - up % 60) if up >= 60 else str(up) + ' saniye'}",
             f"💬 İşlenen güncelleme: <b>{PERF['updates']}</b> · kuyruk: {html.escape(' · '.join(queues) or '-')}",
             f"🧠 Bellek: <b>{cur:.0f} MB</b> (en yüksek {peak:.0f} MB) · CPU: {time.process_time():.0f} sn"
             if cur is not None else f"🧠 CPU: {time.process_time():.0f} sn",
             f"🗄 Veritabanı: {db_mb:.1f} MB · toplu yazma: {PERF['flushes']} kez, {PERF['flushed_rows']} satır · "
             f"bekleyen: {len(_stats_buf) + len(_users_buf)}",
             f"⏱ Döngü gecikmesi: ort {_fmt_ms(sum(lag) / len(lag)) if lag else '-'} · en yüksek {_fmt_ms(max(lag)) if lag else '-'}"
             " (100 ms üstü = bir işlem botu bekletiyor)",
             f"👥 Grup: {n_groups} · Kanal: {n_channels} · Klon: {len(CLONE_APPS)}"]
    hs = [(n, c, tot, mx) for n, (c, tot, mx) in PERF['handlers'].items() if c]
    if hs:
        lines.append("\n🐢 <b>En yavaş (ortalama)</b>")
        for i, (n, c, tot, mx) in enumerate(sorted(hs, key=lambda x: x[2] / x[1], reverse=True)[:8], 1):
            lines.append(f"{i}. <code>{html.escape(n)}</code> — {_fmt_ms(tot / c)} ort · en çok {_fmt_ms(mx)} · {c} kez")
        lines.append("\n⏳ <b>En çok toplam süre</b>")
        for i, (n, c, tot, mx) in enumerate(sorted(hs, key=lambda x: x[2], reverse=True)[:6], 1):
            lines.append(f"{i}. <code>{html.escape(n)}</code> — toplam {_fmt_ms(tot)} · {c} kez")
    return "\n".join(lines)

def _perf_markup():
    return InlineKeyboardMarkup([[ibtn("🔄 Yenile", "perf|r", BLUE), ibtn("🧹 Sıfırla", "perf|z", RED)],
                                 [ibtn("🔙 Panel", "panel|back")]])

async def cmd_perf(update: Update, context):
    """/perf — bot sahibi: hangi işlem ne kadar sürüyor, bellek, kuyruk, veritabanı."""
    if update.effective_user.id != FOUNDER_ID:
        return
    await update.effective_message.reply_text(perf_report(context.application), parse_mode=ParseMode.HTML,
                                              reply_markup=_perf_markup())

async def perf_callback(update: Update, context):
    query = update.callback_query
    if query.from_user.id != FOUNDER_ID:
        await query.answer("Yetkisiz!", show_alert=True)
        return
    if query.data == "perf|z":
        PERF['handlers'].clear()
        PERF.update(since=time.time(), updates=0, flushes=0, flushed_rows=0, lag=[])
        await query.answer("🧹 Ölçümler sıfırlandı")
    else:
        await query.answer("🔄 Yenilendi")
    try:
        await query.edit_message_text(perf_report(context.application), parse_mode=ParseMode.HTML, reply_markup=_perf_markup())
    except BadRequest:
        pass

# ═══════════════════════════ BOT SAHİBİ PANELİ (/panel) ═══════════════════════════
# Gruplar/kanallar 10'arlı sayfa; adına dokun → bilgi; 🚪 → botu çıkar (ayarları tut ya da kaydı da sil).
# 🧹 Temizlik: botun çıkarıldığı, yönetici olmadığı, boş ya da 30 gündür sessiz sohbetleri bulur, toplu çıkar/siler.
PANEL_PAGE = 10
PANEL_IDLE_DAYS = 30
PANEL_EMPTY_MEMBERS = 3   # bu kadar ya da daha az üyeli grup "boş" sayılır (bot + 1-2 kişi)
CLEAN_LABELS = {'dead': "🪦 Botun çıkarıldığı / erişilemeyen", 'noadmin': "⚠️ Botun yönetici olmadığı",
                'empty': f"🕳 Boş (≤{PANEL_EMPTY_MEMBERS} üye)", 'idle': f"💤 {PANEL_IDLE_DAYS} gündür sessiz"}

def _panel_back_kb():
    return InlineKeyboardMarkup([[ibtn("🔙 Geri", "panel|back")]])

def _panel_main():
    with get_db() as conn:
        g = conn.execute("SELECT COUNT(*) FROM channels WHERE mybot(bot_id) AND chat_type IN ('group','supergroup')").fetchone()[0]
        c = conn.execute("SELECT COUNT(*) FROM channels WHERE mybot(bot_id) AND chat_type='channel'").fetchone()[0]
        u = conn.execute("SELECT COUNT(DISTINCT user_id) FROM message_stats WHERE chat_id IN "
                         "(SELECT chat_id FROM channels WHERE mybot(bot_id))").fetchone()[0]
        p = conn.execute("SELECT COUNT(*) FROM bot_users WHERE bot_id = ? AND status = 0", (cur_bot_id(),)).fetchone()[0]
    text = (f"🤖 <b>{html.escape(brand())} Security Bot Paneli</b>\n\n📊 İstatistikler:\n├ Toplam Grup: {g}\n"
            f"├ Toplam Kanal: {c}\n├ Toplam Kullanıcı: {u}\n└ Özelden kullanan: {p}")
    rows = [[ibtn("📢 Kanallar", "panel|ls|c|0", BLUE), ibtn("👥 Gruplar", "panel|ls|g|0", BLUE)],
            [ibtn("🧹 Temizlik", "panel|clean", BLUE), ibtn("📊 İstatistikler", "panel|stats", BLUE)],
            [ibtn("🚫 Engelliler", "panel|blocked", BLUE)]]
    if current_clone() is None:
        rows[-1].append(ibtn("⚡ Performans", "panel|perf", BLUE))
    return text, InlineKeyboardMarkup(rows)

def _panel_chats(kind: str) -> list:
    types = "('channel')" if kind == 'c' else "('group','supergroup')"
    with get_db() as conn:
        return [dict(r) for r in conn.execute(
            f"SELECT chat_id, title, chat_type FROM channels WHERE mybot(bot_id) AND chat_type IN {types} "
            "ORDER BY LOWER(COALESCE(title, chat_id))")]

async def fill_missing_titles(chat_ids: list, limit: int = 5):
    """Adı kayıtlı olmayan sohbetlerin adını Telegram'dan alıp kaydeder (_chat_title veritabanına yazar)."""
    sem = asyncio.Semaphore(limit)

    async def one(cid):
        async with sem:
            await _chat_title(cid)
    await asyncio.gather(*(one(c) for c in chat_ids))

async def fill_all_titles_job(context=None):
    """Açılışta: eski kayıtların eksik grup/kanal adlarını arka planda doldurur."""
    with get_db() as conn:
        ids = [r[0] for r in conn.execute("SELECT chat_id FROM channels WHERE title IS NULL OR title = '' OR title = chat_id")]
    if ids:
        await fill_missing_titles(ids, limit=3)
        logger.info(f"{len(ids)} sohbetin adı güncellendi")

async def _panel_fill_page(kind: str, page: int):
    items = _panel_chats(kind)
    pages = max(1, (len(items) + PANEL_PAGE - 1) // PANEL_PAGE)
    page = max(0, min(page, pages - 1))
    missing = [it['chat_id'] for it in items[page * PANEL_PAGE:(page + 1) * PANEL_PAGE]
               if not it['title'] or it['title'] == it['chat_id']]
    if missing:
        await fill_missing_titles(missing)

def _panel_list(kind: str, page: int):
    items = _panel_chats(kind)
    pages = max(1, (len(items) + PANEL_PAGE - 1) // PANEL_PAGE)
    page = max(0, min(page, pages - 1))
    icon, name = ("📢", "Kanallar") if kind == 'c' else ("👥", "Gruplar")
    text = (f"{icon} <b>{name}</b> ({len(items)}) — sayfa {page + 1}/{pages}\n\n"
            "Adına dokun: bilgi · 🚪: botu çıkar")
    rows = []
    for it in items[page * PANEL_PAGE:(page + 1) * PANEL_PAGE]:
        cid = it['chat_id']
        rows.append([ibtn(f"{icon} {(it['title'] or cid)[:30]}", f"panel|info|{cid}|{kind}|{page}"),
                     ibtn("🚪", f"panel|lq|{cid}|{kind}|{page}", RED)])
    if pages > 1:
        rows.append([ibtn("◀️ Önceki", f"panel|ls|{kind}|{(page - 1) % pages}"),
                     ibtn(f"{page + 1}/{pages}", f"panel|ls|{kind}|{page}"),
                     ibtn("Sonraki ▶️", f"panel|ls|{kind}|{(page + 1) % pages}")])
    if not items:
        text = "📢 Kayıtlı kanal yok." if kind == 'c' else "👥 Kayıtlı grup yok."
    rows.append([ibtn("🔙 Geri", "panel|back")])
    return text, InlineKeyboardMarkup(rows)

async def _panel_info(cid: str, kind: str, page: int):
    flush_writes()
    with get_db() as conn:
        ch = conn.execute("SELECT * FROM channels WHERE chat_id = ?", (cid,)).fetchone()
        last = conn.execute("SELECT MAX(sent_at) FROM message_stats WHERE chat_id = ?", (cid,)).fetchone()[0]
        n7 = conn.execute("SELECT COUNT(*) FROM message_stats WHERE chat_id = ? AND sent_at >= ?",
                          (cid, time.time() - 7 * 86400)).fetchone()[0]
    back = [ibtn("🔙 Listeye dön", f"panel|ls|{kind}|{page}")]
    if not ch:
        return "Bu sohbetin kaydı yok (silinmiş).", InlineKeyboardMarkup([back])
    ch = dict(ch)
    title, link, members, status = ch.get('title') or cid, None, '?', None
    try:
        chat = await bot.get_chat(cid)
        title = chat.title or title
        link = f"https://t.me/{chat.username}" if getattr(chat, 'username', None) else None
        try:
            members = await bot.get_chat_member_count(cid)
        except TelegramError:
            pass
        status = (await bot.get_chat_member(cid, bot_id_for(cid))).status
        if title != ch.get('title'):
            with get_db() as conn:
                conn.execute("UPDATE channels SET title = ? WHERE chat_id = ?", (title, cid))
    except TelegramError as e:
        logger.debug(f"Panel bilgi {cid}: {e}")
    st = {'administrator': "✅ yönetici", 'creator': "✅ sahip", 'member': "⚠️ üye (yönetici değil)",
          'left': "❌ grupta değil", 'kicked': "❌ atılmış"}.get(status, "❌ erişilemiyor (bot çıkarılmış olabilir)")
    s = json.loads(ch.get('settings') or '{}')
    active = [lbl for k, (lbl, skey, _, _) in PROTECTIONS.items() if s.get(skey)]
    created = (ch.get('created_at') or '')[:10]
    text = (f"{'📢' if ch.get('chat_type') == 'channel' else '👥'} <b>{html.escape(title)}</b>\n\n"
            f"🆔 <code>{cid}</code>" + (f" · {html.escape(link)}" if link else "") + "\n"
            f"👥 Üye: {members} · 🤖 Bot: {st}\n"
            f"📅 Kayıt: {html.escape(created) or '-'}" +
            (f" · Ekleyen: {mention_html(ch['added_by'], str(ch['added_by']))}" if ch.get('added_by') else "") + "\n"
            f"💬 Son mesaj: {(_ago(time.time() - last) if last else 'hiç')} · 7 günde {n7} mesaj\n"
            f"🛡 Açık korumalar: {', '.join(active) or 'yok'}")
    if status in ('administrator', 'creator', 'member'):
        act = [ibtn("🚪 Botu çıkar", f"panel|lq|{cid}|{kind}|{page}", RED)]
    else:
        act = [ibtn("🗑 Kaydı sil", f"panel|lv|{cid}|d|{kind}|{page}", RED)]
    rows = [act]
    if ch.get('chat_type') != 'channel':
        rows.insert(0, [ibtn("📋 Ayarlarını diğer gruplara uygula", f"panel|ap|{cid}|{kind}|{page}", BLUE)])
    return text, InlineKeyboardMarkup(rows + [back])

def purge_chat(chat_id: str) -> int:
    """Sohbetin bütün kayıtlarını (ayarlar, rütbeler, istatistikler…) siler. Dönüş: silinen satır."""
    cid = str(chat_id)
    flush_writes()
    n = 0
    with get_db() as conn:
        tables = [r[0] for r in conn.execute("SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%'")]
        for t in tables:
            if 'chat_id' in {r[1] for r in conn.execute(f'PRAGMA table_info("{t}")')}:
                n += conn.execute(f'DELETE FROM "{t}" WHERE chat_id = ? OR chat_id = ?',
                                  (cid, int(cid) if cid.lstrip('-').isdigit() else cid)).rowcount
    _invalidate_settings(cid)
    for cache in (_chat_bot_map, _title_cache, _tg_admin_cache, _filter_cache):
        cache.pop(cid, None)
    return n

async def leave_chat(chat_id: str, purge: bool) -> str | None:
    """Botu sohbetten çıkarır; purge=True ise kaydını da siler. Dönüş: hata metni ya da None."""
    try:
        await bot.leave_chat(chat_id)
    except TelegramError as e:
        err = str(e).lower()
        if not any(w in err for w in ('not found', 'not a member', 'kicked', 'forbidden', 'chat_id_invalid', 'left')):
            return friendly_error(e)
    if purge:
        purge_chat(chat_id)
    return None

async def panel_scan(chats: list) -> dict:
    """Temizlik taraması: her sohbette botun durumu, üye sayısı ve son mesaj."""
    res = {k: [] for k in CLEAN_LABELS}
    flush_writes()
    cutoff = time.time() - PANEL_IDLE_DAYS * 86400
    with get_db() as conn:
        last = {r[0]: r[1] for r in conn.execute("SELECT chat_id, MAX(sent_at) FROM message_stats GROUP BY chat_id")}
    sem = asyncio.Semaphore(5)

    async def check(c):
        cid = c['chat_id']
        async with sem:
            try:
                me = await bot.get_chat_member(cid, bot_id_for(cid))
            except TelegramError:
                res['dead'].append(cid)
                return
            if me.status in ('left', 'kicked'):
                res['dead'].append(cid)
                return
            if me.status not in ('administrator', 'creator'):
                res['noadmin'].append(cid)
            if c['chat_type'] == 'channel':
                return
            try:
                if await bot.get_chat_member_count(cid) <= PANEL_EMPTY_MEMBERS:
                    res['empty'].append(cid)
                    return
            except TelegramError:
                pass
            created = c.get('created_at') or ''
            old = True
            try:
                old = datetime.strptime(created[:19], '%Y-%m-%d %H:%M:%S').replace(tzinfo=timezone.utc).timestamp() < cutoff
            except ValueError:
                pass
            if old and (last.get(cid) or 0) < cutoff:
                res['idle'].append(cid)
    await asyncio.gather(*(check(c) for c in chats))
    return res

def _clean_summary(res: dict, n: int):
    lines = [f"🧹 <b>Temizlik taraması</b> — {n} sohbet tarandı\n"]
    rows = []
    for k, lbl in CLEAN_LABELS.items():
        cnt = len(res.get(k, []))
        lines.append(f"{lbl}: <b>{cnt}</b>")
        if cnt:
            act = "🗑 Kayıtları sil" if k == 'dead' else "🚪 Çık + sil"
            rows.append([ibtn(f"{act} ({cnt})", f"panel|cq|{k}", RED), ibtn("📋 Göster", f"panel|cv|{k}")])
    if not rows:
        lines.append("\n✅ Temizlenecek bir şey yok.")
    lines.append("\nNot: ‘Çık + sil’ botu o sohbetlerden çıkarır ve ayarlarını siler.")
    rows.append([ibtn("🔄 Yeniden tara", "panel|clean"), ibtn("🔙 Geri", "panel|back")])
    return "\n".join(lines), InlineKeyboardMarkup(rows)

async def cmd_panel(update: Update, context):
    if not is_bot_owner(update.effective_user.id):
        return
    if update.effective_chat.type != 'private':
        await update.effective_message.reply_text("Bu komut sadece özelden çalışır!")
        return
    text, kb = _panel_main()
    await update.effective_message.reply_text(text, reply_markup=kb, parse_mode=ParseMode.HTML)

async def panel_callback(update: Update, context):
    query = update.callback_query
    if not is_bot_owner(query.from_user.id):
        await query.answer("Yetkisiz!", show_alert=True)
        return
    parts = query.data.split("|")
    action = parts[1] if len(parts) > 1 else ''
    # eski butonlar (önceki sürüm)
    if action in ('channels', 'groups'):
        parts, action = ['panel', 'ls', 'c' if action == 'channels' else 'g', '0'], 'ls'
    elif action == 'chatinfo':
        parts, action = ['panel', 'info', parts[2], 'g', '0'], 'info'

    async def show(text, kb):
        await query.edit_message_text(text, reply_markup=kb, parse_mode=ParseMode.HTML, disable_web_page_preview=True)

    if action == 'ls':
        await query.answer()
        await _panel_fill_page(parts[2], int(parts[3]))  # adı bilinmeyenler Telegram'dan alınır ve kaydedilir
        await show(*_panel_list(parts[2], int(parts[3])))
    elif action == 'info':
        await query.answer()
        await show(*await _panel_info(parts[2], parts[3], int(parts[4])))
    elif action == 'ap':
        cid, kind, page = parts[2], parts[3], int(parts[4])
        await query.answer()
        with get_db() as conn:
            r = conn.execute("SELECT title FROM channels WHERE chat_id = ?", (cid,)).fetchone()
            n = conn.execute("SELECT COUNT(*) FROM channels WHERE mybot(bot_id) AND chat_type IN ('group','supergroup') "
                             "AND chat_id != ?", (cid,)).fetchone()[0]
        title = html.escape((r['title'] if r else None) or cid)
        await show(f"📋 <b>{title}</b> grubunun ayarları diğer <b>{n}</b> gruba uygulansın mı?\n\n"
                   "Kopyalanır: koruma ayarları, cezalar, captcha, gece modu, uyarı sınırı vb.\n"
                   "Kopyalanmaz: hoş geldin/veda/kurallar mesajı, kanal zorunluluğu, kilitler, gruba özel listeler.\n"
                   "<b>+ listeler</b>: yasaklı kelime ve izinli link listeleri de eklenir (mevcutlar silinmez).",
                   InlineKeyboardMarkup([[ibtn("✅ Uygula", f"panel|apy|{cid}|s", GREEN),
                                          ibtn("✅ Uygula + listeler", f"panel|apy|{cid}|l", GREEN)],
                                         [ibtn("↩️ Vazgeç", f"panel|info|{cid}|{kind}|{page}")]]))
    elif action == 'apy':
        cid, mode = parts[2], parts[3]
        if not get_channel_settings(cid):
            await query.answer("Kaynak grubun kaydı yok.", show_alert=True)
            return
        with get_db() as conn:
            targets = [r['chat_id'] for r in conn.execute(
                "SELECT chat_id FROM channels WHERE mybot(bot_id) AND chat_type IN ('group','supergroup')")]
        n = copy_settings_to(cid, targets, lists=(mode == 'l'))
        await query.answer(f"✅ {n} gruba uygulandı", show_alert=True)
        await send_log(cid, f"📋 Bu grubun ayarları {n} gruba uygulandı | {mention(query.from_user)}", ParseMode.HTML)
        await show(*await _panel_info(cid, 'g', 0))
    elif action == 'lq':
        cid, kind, page = parts[2], parts[3], int(parts[4])
        await query.answer()
        with get_db() as conn:
            r = conn.execute("SELECT title FROM channels WHERE chat_id = ?", (cid,)).fetchone()
        title = html.escape((r['title'] if r else None) or cid)
        await show(f"🚪 Bot <b>{title}</b> sohbetinden çıkarılsın mı?\n\n"
                   "• <b>Ayarları sakla</b>: bot tekrar eklenirse ayarlar geri gelir.\n"
                   "• <b>Kaydı da sil</b>: ayarlar, rütbeler ve istatistikler silinir.",
                   InlineKeyboardMarkup([[ibtn("🚪 Çık, ayarları sakla", f"panel|lv|{cid}|k|{kind}|{page}", RED)],
                                         [ibtn("🗑 Çık ve kaydı sil", f"panel|lv|{cid}|d|{kind}|{page}", RED)],
                                         [ibtn("↩️ Vazgeç", f"panel|info|{cid}|{kind}|{page}")]]))
    elif action == 'lv':
        cid, mode, kind, page = parts[2], parts[3], parts[4], int(parts[5])
        err = await leave_chat(cid, purge=(mode == 'd'))
        if err:
            await query.answer(f"Çıkılamadı: {err}"[:190], show_alert=True)
            return
        await query.answer("✅ Çıkıldı" + (" ve kayıt silindi" if mode == 'd' else ""))
        logger.info(f"Panelden sohbetten çıkıldı: {cid} (kayıt {'silindi' if mode == 'd' else 'saklandı'})")
        await _panel_fill_page(kind, page)
        await show(*_panel_list(kind, page))
    elif action == 'clean':
        await query.answer("Taranıyor…")
        with get_db() as conn:
            chats = [dict(r) for r in conn.execute("SELECT chat_id, chat_type, created_at FROM channels WHERE mybot(bot_id)")]
        await show(f"🧹 {len(chats)} sohbet taranıyor, biraz sürebilir…", None)
        res = await panel_scan(chats)
        context.user_data['panel_clean'] = {'at': time.time(), 'res': res}
        await show(*_clean_summary(res, len(chats)))
    elif action in ('cq', 'cv', 'cx'):
        scan = context.user_data.get('panel_clean')
        k = parts[2] if len(parts) > 2 else ''
        if not scan or time.time() - scan['at'] > 900 or k not in CLEAN_LABELS:
            await query.answer("Tarama eskidi, yeniden tara.", show_alert=True)
            return
        ids = scan['res'][k]
        if action == 'cv':
            await query.answer()
            with get_db() as conn:
                titles = {r['chat_id']: r['title'] for r in conn.execute(
                    f"SELECT chat_id, title FROM channels WHERE chat_id IN ({','.join('?' * len(ids))})", ids)} if ids else {}
            body = "\n".join(f"• {html.escape(titles.get(c) or c)} (<code>{c}</code>)" for c in ids[:60])
            more = f"\n… ve {len(ids) - 60} tane daha" if len(ids) > 60 else ""
            await show(f"{CLEAN_LABELS[k]}:\n<blockquote expandable>{body or '-'}</blockquote>{more}",
                       InlineKeyboardMarkup([[ibtn(f"{'🗑 Sil' if k == 'dead' else '🚪 Çık + sil'} ({len(ids)})", f"panel|cq|{k}", RED)],
                                             [ibtn("🔙 Taramaya dön", "panel|cs")]]))
        elif action == 'cq':
            await query.answer()
            verb = "kayıtları silinsin" if k == 'dead' else "sohbetlerden çıkılsın ve kayıtları silinsin"
            await show(f"⚠️ {CLEAN_LABELS[k]}: <b>{len(ids)}</b> sohbetin {verb} mi? Bu geri alınamaz.",
                       InlineKeyboardMarkup([[ibtn("✅ Evet", f"panel|cx|{k}", RED), ibtn("↩️ Vazgeç", "panel|cs")]]))
        else:
            await query.answer("İşleniyor…")
            done, failed = 0, 0
            for cid in ids:
                if k == 'dead':
                    purge_chat(cid)
                    done += 1
                elif await leave_chat(cid, purge=True):
                    failed += 1
                else:
                    done += 1
            for other in scan['res'].values():
                other[:] = [c for c in other if c not in set(ids)]
            logger.info(f"Panel temizliği ({k}): {done} sohbet, {failed} başarısız")
            text, kb = _clean_summary(scan['res'], sum(len(v) for v in scan['res'].values()))
            await show(f"✅ {done} sohbet temizlendi" + (f", {failed} başarısız" if failed else "") + "\n\n" + text, kb)
    elif action == 'cs':
        scan = context.user_data.get('panel_clean')
        await query.answer()
        if not scan:
            await show(*_panel_main())
        else:
            await show(*_clean_summary(scan['res'], sum(len(v) for v in scan['res'].values())))
    elif action == 'perf':
        if query.from_user.id != FOUNDER_ID:
            await query.answer("Sadece ana bot sahibi.", show_alert=True)
            return
        await query.answer()
        await show(perf_report(context.application), _perf_markup())
    elif action == 'blocked':
        await query.answer()
        if query.from_user.id != FOUNDER_ID:
            await show("Engelli listesi sadece ana bot sahibine açıktır.", _panel_back_kb())
            return
        with get_db() as conn:
            rows = conn.execute("SELECT entity_id, entity_type, reason FROM blocked_entities LIMIT 30").fetchall()
        body = "\n".join(f"• {html.escape(str(r['entity_type']))}: <code>{html.escape(str(r['entity_id']))}</code> — "
                         f"{html.escape(r['reason'] or '-')}" for r in rows)
        await show("🚫 <b>Engellenenler</b>\n\n" + (body or "Engellenmiş kimse yok."), _panel_back_kb())
    elif action == 'stats':
        await query.answer()
        flush_writes()
        sub = "SELECT chat_id FROM channels WHERE mybot(bot_id)"
        with get_db() as conn:
            def q(sql):
                return conn.execute(sql).fetchone()[0]
            groups = q("SELECT COUNT(*) FROM channels WHERE mybot(bot_id) AND chat_type IN ('group','supergroup')")
            chans = q("SELECT COUNT(*) FROM channels WHERE mybot(bot_id) AND chat_type = 'channel'")
            users = q(f"SELECT COUNT(DISTINCT user_id) FROM message_stats WHERE chat_id IN ({sub})")
            msgs = q(f"SELECT COUNT(*) FROM message_stats WHERE chat_id IN ({sub})")
            bans = q(f"SELECT COUNT(*) FROM ban_list WHERE chat_id IN ({sub})")
        await show(f"📊 <b>Bot İstatistikleri</b>\n\n├ Toplam Grup: {groups}\n├ Toplam Kanal: {chans}\n"
                   f"├ Toplam Kullanıcı: {users}\n├ Toplam Mesaj Kaydı: {msgs}\n└ Toplam Ban: {bans}", _panel_back_kb())
    else:  # back
        await query.answer()
        await show(*_panel_main())

# ── Notlar (/save, /not, #isim) ──
_NOTE_NAME = re.compile(r'^[\w\-]{1,32}$')

async def cmd_save_note(update: Update, context):
    """/save isim metin  veya bir mesaja yanıt olarak /save isim"""
    msg = update.effective_message
    chat_id = _get_effective_chat_id(update, context)
    if not chat_id or not get_channel_settings(chat_id):
        await msg.reply_text("Önce /kanal ile seç!")
        return
    if not await require(update, chat_id, 'can_content'):
        return
    if not context.args or not _NOTE_NAME.match(context.args[0]):
        await msg.reply_text("Kullanım: /save <isim> <metin>  (veya bir mesaja yanıt: /save <isim>)")
        return
    name = context.args[0].lower()
    content, file_id, file_type = None, None, None
    parts = msg.text_html.split(maxsplit=2) if msg.text else []
    if len(parts) > 2:
        content = parts[2]
    elif msg.reply_to_message:
        r = msg.reply_to_message
        content = r.text_html or r.caption_html or None
        for ft in ('photo', 'video', 'animation', 'document', 'sticker', 'voice', 'audio'):
            obj = getattr(r, ft, None)
            if obj:
                file_id = obj[-1].file_id if ft == 'photo' else obj.file_id
                file_type = ft
                break
    if not content and not file_id:
        await msg.reply_text("Not içeriği boş olamaz.")
        return
    async with _db_lock:
        with get_db() as conn:
            conn.execute("""INSERT OR REPLACE INTO notes (chat_id, name, content, file_id, file_type, created_by, created_at)
                            VALUES (?, ?, ?, ?, ?, ?, ?)""",
                         (chat_id, name, content, file_id, file_type, update.effective_user.id, time.time()))
            conn.commit()
    await msg.reply_text(f"✅ Not kaydedildi: #{name}")

async def _send_note(chat_id: str, name: str, reply_to):
    with get_db() as conn:
        row = conn.execute("SELECT * FROM notes WHERE chat_id = ? AND name = ?", (chat_id, name.lower())).fetchone()
    if not row:
        return False
    rich = build_rich(row['content'] or '', {'type': row['file_type'], 'id': row['file_id']} if row['file_id'] else None)
    await send_rich(reply_to.chat_id, rich, reply_msg=reply_to, users=[getattr(reply_to, 'from_user', None)],
                    title=await _chat_title(chat_id))
    return True

async def cmd_get_note(update: Update, context):
    msg = update.effective_message
    chat_id = _get_effective_chat_id(update, context)
    if not chat_id or not context.args:
        await msg.reply_text("Kullanım: /not <isim>")
        return
    if not await _send_note(chat_id, context.args[0], msg):
        await msg.reply_text("Böyle bir not yok. /notlar ile listeyi gör.")

async def hashtag_note_handler(update: Update, context):
    msg = update.effective_message
    if not msg or not msg.text or msg.chat.type == 'private':
        return
    m = re.match(r'^#([\w\-]{1,32})\b', msg.text)
    if m:
        await _send_note(str(msg.chat_id), m.group(1), msg)

async def cmd_notes(update: Update, context):
    chat_id = _get_effective_chat_id(update, context)
    if not chat_id:
        return
    with get_db() as conn:
        rows = conn.execute("SELECT name FROM notes WHERE chat_id = ? ORDER BY name", (chat_id,)).fetchall()
    if not rows:
        await update.effective_message.reply_text("Kayıtlı not yok. /save ile ekle.")
        return
    await update.effective_message.reply_text(
        "📝 <b>Notlar</b>\n<blockquote expandable>" + "\n".join(f"• #{r['name']}" for r in rows) +
        "</blockquote>\nGörmek için grupta #isim yaz.", parse_mode=ParseMode.HTML)

async def cmd_delete_note(update: Update, context):
    chat_id = _get_effective_chat_id(update, context)
    if not chat_id:
        await update.effective_message.reply_text("Önce /kanal ile seç!")
        return
    if not await require(update, chat_id, 'can_content'):
        return
    if not context.args:
        await update.effective_message.reply_text("Kullanım: /notsil <isim>")
        return
    async with _db_lock:
        with get_db() as conn:
            n = conn.execute("DELETE FROM notes WHERE chat_id = ? AND name = ?", (chat_id, context.args[0].lower())).rowcount
            conn.commit()
    await update.effective_message.reply_text("✅ Not silindi." if n else "Böyle bir not yok.")

# ═══════════════════════════ HIZLI KURULUM ═══════════════════════════
# Bot eklenince ekleyen kişiye özelden gelir; /kurulum ile tekrar açılır. Butonlarla: paket → hoş geldin → korumalar → özet.
SETUP_TOGGLES = [  # (ayar anahtarı, etiket)
    ('anti_link', "🔗 Link engeli"), ('anti_spam_flood', "🌊 Flood"), ('spam_protection', "🔁 Tekrar spam"),
    ('captcha_enabled', "🧩 Captcha"), ('media_shield', "🔞 Uygunsuz medya"), ('anti_forward', "↪️ İletme engeli"),
    ('anti_raid', "🚨 Raid koruması"), ('newbie_minutes', "🐣 Yeni üye kısıtı (60 dk)"), ('word_ban_enabled', "🔤 Kelime filtresi"),
]
SETUP_PRESETS = {
    'light':  ("🟢 Hafif", {'anti_link', 'anti_spam_flood'}),
    'normal': ("🟡 Normal", {'anti_link', 'anti_spam_flood', 'spam_protection', 'captcha_enabled', 'media_shield'}),
    'strict': ("🔴 Sıkı", {'anti_link', 'anti_spam_flood', 'spam_protection', 'captcha_enabled', 'media_shield',
                          'newbie_minutes', 'anti_forward', 'anti_raid'}),
}

def _setup_state(context, cid: str) -> dict:
    st = context.user_data.get('setup')
    if not st or st.get('cid') != cid:
        s = (get_channel_settings(cid) or {}).get('settings', {})
        st = {'cid': cid, 'preset': None, 'welcome': 'def' if s.get('welcome_enabled', True) else 'off',
              'on': {k for k, _ in SETUP_TOGGLES if s.get(k)}}
        context.user_data['setup'] = st
    return st

async def render_setup(cid: str, step: str, st: dict):
    title = html.escape(await _chat_title(cid))
    rows = []
    if step == 'start':
        text = (f"⚡ <b>Hızlı kurulum</b> — {title}\n\n<b>1/3</b> Bir koruma paketi seç. Sonra hepsini tek tek değiştirebilirsin.\n\n"
                "🟢 <b>Hafif</b>: link + flood\n🟡 <b>Normal</b>: + tekrar spam, captcha, uygunsuz medya\n"
                "🔴 <b>Sıkı</b>: + yeni üye kısıtı, iletme engeli, raid koruması")
        rows = [[ibtn(SETUP_PRESETS[k][0], f"ks|{cid}|p|{k}", BLUE) for k in ('light', 'normal', 'strict')],
                [ibtn("⚙️ Kendim seçeyim", f"ks|{cid}|p|custom", BLUE)],
                [ibtn("✖️ Şimdilik geç", f"ks|{cid}|x", RED)]]
    elif step == 'welcome':
        cur = {'off': "Kapalı", 'def': "Varsayılan", 'own': "Kendi metnim"}[st['welcome']]
        text = (f"⚡ <b>Hızlı kurulum</b> — {title}\n\n<b>2/3</b> Yeni gelenlere hoş geldin mesajı gönderilsin mi?\n"
                f"Şu an: <b>{cur}</b>")
        rows = [[ibtn("🚫 Kapalı", f"ks|{cid}|w|off", RED), ibtn("👋 Varsayılan", f"ks|{cid}|w|def", GREEN)],
                [ibtn("✏️ Kendi metnimi yazacağım", f"ks|{cid}|w|own", BLUE)]]
    elif step == 'prot':
        text = (f"⚡ <b>Hızlı kurulum</b> — {title}\n\n<b>3/3</b> Hangi korumalar açık olsun? Dokunarak aç/kapat.")
        rows = [[toggle_btn(lbl, k in st['on'], f"ks|{cid}|t|{k}")] for k, lbl in SETUP_TOGGLES]
        rows.append([ibtn("➡️ Devam", f"ks|{cid}|s|sum", GREEN)])
    else:  # özet
        on = [lbl for k, lbl in SETUP_TOGGLES if k in st['on']]
        wel = {'off': "kapalı", 'def': "varsayılan metin", 'own': "kendi metnin"}[st['welcome']]
        text = (f"⚡ <b>Hızlı kurulum</b> — {title}\n\n<b>Özet</b>\n"
                f"🛡 Açık korumalar: {', '.join(on) if on else 'yok'}\n👋 Hoş geldin: {wel}\n\n"
                "Uygula'ya bas, ayarlar kaydedilsin. Sonradan /settings ile her şeyi değiştirebilirsin.")
        rows = [[ibtn("✅ Uygula", f"ks|{cid}|a|go", GREEN)],
                [ibtn("🛡 Korumaları değiştir", f"ks|{cid}|s|prot", BLUE), ibtn("👋 Hoş geldin", f"ks|{cid}|s|welcome", BLUE)]]
    return text, InlineKeyboardMarkup(rows)

def apply_setup(cid: str, st: dict):
    channel = get_channel_settings(cid)
    s = channel['settings']
    for k, _ in SETUP_TOGGLES:
        if k == 'newbie_minutes':
            s[k] = 60 if k in st['on'] else 0
        else:
            s[k] = k in st['on']
    s['welcome_enabled'] = st['welcome'] != 'off'
    if st['welcome'] == 'def':
        s['welcome_msg'] = _default_channel_settings()['welcome_msg']
        s.pop('welcome_rich', None)
    channel['settings'] = s
    save_channel_settings(cid, channel)

async def send_setup_wizard(chat_id_dm: int, cid: str, context) -> bool:
    """Kurulum sihirbazını özelden gönderir. Bot o kişiye yazamıyorsa False."""
    st = _setup_state(context, cid) if context else {'cid': cid, 'preset': None, 'welcome': 'def', 'on': set()}
    text, markup = await render_setup(cid, 'start', st)
    try:
        await bot.send_message(chat_id_dm, text, reply_markup=markup, parse_mode=ParseMode.HTML)
        return True
    except TelegramError as e:
        logger.debug(f"Kurulum sihirbazı gönderilemedi {chat_id_dm}: {e}")
        return False

async def cmd_kurulum(update: Update, context):
    """/kurulum — hızlı kurulum. Grupta yazılırsa özelden açmak için buton verir."""
    msg = update.effective_message
    chat = update.effective_chat
    if chat.type != 'private':
        cid = str(chat.id)
        if not get_channel_settings(cid):
            await msg.reply_text("Bu grup kayıtlı değil. Önce botu yönetici yap.")
            return
        if not await require(update, cid, 'can_manage_settings'):
            return
        await msg.reply_text("⚡ Hızlı kurulum bota özelden yapılır:", reply_markup=InlineKeyboardMarkup(
            [[InlineKeyboardButton("⚡ Kurulumu aç", url=f"https://t.me/{context.bot.username}?start=kurulum_{cid}")]]))
        return
    cid = context.user_data.get('selected_channel')
    if context.args and context.args[0].startswith('kurulum_'):
        cid = context.args[0][len('kurulum_'):]
    if not cid or not get_channel_settings(cid):
        await msg.reply_text("Önce 🛡 Gruplarım ile bir grup seç, sonra /kurulum yaz.")
        return
    if not await require(update, cid, 'can_manage_settings'):
        return
    context.user_data['selected_channel'] = cid
    context.user_data.pop('setup', None)
    st = _setup_state(context, cid)
    text, markup = await render_setup(cid, 'start', st)
    await msg.reply_text(text, reply_markup=markup, parse_mode=ParseMode.HTML)

async def setup_callback(update: Update, context):
    """ks|cid|op|arg — hızlı kurulum butonları."""
    query = update.callback_query
    parts = query.data.split('|')
    cid, op, arg = parts[1], parts[2], (parts[3] if len(parts) > 3 else '')
    if not get_channel_settings(cid):
        await query.answer("Grup bulunamadı.", show_alert=True)
        return
    if not has_specific_permission(cid, query.from_user.id, 'can_manage_settings'):
        await deny(update, 'can_manage_settings')
        return
    st = _setup_state(context, cid)
    step, note = 'start', ''
    if op == 'x':
        await query.answer()
        await query.edit_message_text("Kurulum geçildi. İstediğin zaman /kurulum ile açabilirsin.")
        return
    if op == 'p':
        if arg in SETUP_PRESETS:
            st['preset'], st['on'] = arg, set(SETUP_PRESETS[arg][1])
        else:
            st['preset'] = 'custom'
        step = 'welcome'
    elif op == 'w':
        st['welcome'] = arg if arg in ('off', 'def', 'own') else 'def'
        step = 'prot' if st['preset'] == 'custom' else 'sum'
        if arg == 'own':
            await _ask_input(query, context, cid, 'welcome')  # sorguyu kendisi yanıtlar
            text, markup = await render_setup(cid, step, st)
            await query.edit_message_text(text, reply_markup=markup, parse_mode=ParseMode.HTML)
            return
    elif op == 't':
        st['on'] ^= {arg} if arg in dict(SETUP_TOGGLES) else set()
        step = 'prot'
    elif op == 's':
        step = arg if arg in ('welcome', 'prot', 'sum') else 'sum'
    elif op == 'a':
        apply_setup(cid, st)
        context.user_data.pop('setup', None)
        await query.answer("✅ Ayarlar kaydedildi")
        await query.edit_message_text(
            f"✅ <b>Kurulum tamam!</b> — {html.escape(await _chat_title(cid))}\n\n"
            "Ayrıntılı ayarlar için /settings · Otomatik yanıtlar için grupta /filter", parse_mode=ParseMode.HTML)
        await send_log(cid, f"⚡ Hızlı kurulum uygulandı | {mention(query.from_user)}", ParseMode.HTML)
        return
    await query.answer(note)
    text, markup = await render_setup(cid, step, st)
    try:
        await query.edit_message_text(text, reply_markup=markup, parse_mode=ParseMode.HTML)
    except BadRequest as e:
        if 'not modified' not in str(e).lower():
            raise

# ── Metin tabanlı otomatik yanıt (/filter) — her sohbette ayrı ──
FILTER_LIMIT = 150
FILTER_COOLDOWN = 5  # aynı filtre aynı grupta en fazla 5 sn'de bir yanıt verir
FILTER_MEDIA = ('sticker', 'photo', 'animation', 'video', 'voice', 'audio', 'document', 'video_note')
_filter_cache: dict = {}
_filter_last: dict = {}

def filter_norm(text: str) -> str:
    """Eşleştirme biçimi: Türkçe/büyük-küçük harf/noktalama farkı yok sayılır ("Selam!" == "selam")."""
    t = unicodedata.normalize('NFKC', text or '').replace('İ', 'i').replace('I', 'ı').lower()
    t = re.sub(r'[^\w\s]', ' ', t).translate(_TR_FOLD)  # noktalama leetspeak'e çevrilmeden atılır ("Selam!" → "selam")
    t = re.sub(r'(.)\1{2,}', r'\1', t)  # "selaaam" → "selam"
    return re.sub(r'\s+', ' ', t).strip()

def chat_filters(chat_id: str) -> list:
    chat_id = str(chat_id)
    if chat_id not in _filter_cache:
        with get_db() as conn:
            _filter_cache[chat_id] = [dict(r) for r in conn.execute(
                "SELECT rowid AS fid, * FROM chat_filters WHERE chat_id = ? ORDER BY LENGTH(trigger_norm) DESC", (chat_id,))]
    return _filter_cache[chat_id]

def _filter_changed(chat_id: str):
    _filter_cache.pop(str(chat_id), None)

def match_filter(chat_id: str, text: str):
    norm = filter_norm(text)
    if not norm:
        return None
    for f in chat_filters(chat_id):
        if f['mode'] == 'exact' and norm == f['trigger_norm']:
            return f
        if f['mode'] == 'contains' and re.search(r'(?<!\w)' + re.escape(f['trigger_norm']) + r'(?!\w)', norm):
            return f
    return None

def _parse_trigger(raw: str):
    """'selam' → tam eşleşme; '*selam*' → içerirse. Dönüş: (görünen, normal, mod) veya None."""
    raw = raw.strip()
    mode = 'exact'
    if len(raw) > 2 and raw.startswith('*') and raw.endswith('*'):
        raw, mode = raw[1:-1].strip(), 'contains'
    norm = filter_norm(raw)
    if not norm or len(raw) > 100:
        return None
    return raw, norm, mode

def _tail_html(msg, text: str, tail_plain: str) -> str:
    """Komut metninin sonundaki tail_plain kısmının biçimli HTML'i."""
    idx = len(text.rstrip()) - len(tail_plain)
    return html_after(msg, idx) if idx >= 0 and text.rstrip().endswith(tail_plain) else html.escape(tail_plain, quote=False)

def _split_filter_args(text: str):
    """'/filter "iyi akşamlar" Size de' → ('iyi akşamlar', 'Size de'); '/filter selam Aleyküm selam' → ('selam', ...)"""
    body = text.split(maxsplit=1)[1] if len(text.split(maxsplit=1)) > 1 else ''
    body = body.strip()
    m = re.match(r'^["“”\'](.+?)["“”\']\s*(.*)$', body, re.S)
    if m:
        return m.group(1), m.group(2).strip()
    first, _, rest = body.partition(' ')
    return first, rest.strip()

async def cmd_filter(update: Update, context):
    """/filter — bir mesaja yanıtla: tetikleyici o mesaj, yanıt yazdığın metin.
    Medyaya (sticker/foto…) yanıtla: /filter <tetikleyici> → bot o medya ile cevap verir.
    Yanıtsız: /filter <tetikleyici> <yanıt> · çok kelimeli tetikleyici: /filter "iyi akşamlar" yanıt · içerirse: *kelime*"""
    msg = update.effective_message
    chat_id = _get_effective_chat_id(update, context)
    if not chat_id or not get_channel_settings(chat_id):
        await msg.reply_text("Önce /kanal ile grup seç!")
        return
    if not await require(update, chat_id, 'can_filters'):
        return
    text = msg.text or ''
    reply = msg.reply_to_message
    trigger_raw = answer = None
    file_id = file_type = None
    if reply and any(getattr(reply, ft, None) for ft in FILTER_MEDIA):
        trigger_raw, extra = _split_filter_args(text)
        for ft in FILTER_MEDIA:
            obj = getattr(reply, ft, None)
            if obj:
                file_id, file_type = (obj[-1].file_id if ft == 'photo' else obj.file_id), ft
                break
        answer = _tail_html(msg, text, extra) if extra else msg_html(reply)
    elif reply and (reply.text or reply.caption):
        trigger_raw = reply.text or reply.caption
        answer = cmd_args_html(msg, 1)
    else:
        trigger_raw, answer = _split_filter_args(text)
        answer = _tail_html(msg, text, answer) if answer else ''
    parsed = _parse_trigger(trigger_raw or '')
    if not parsed or (not answer and not file_id):
        await msg.reply_text(
            "🧩 <b>Filtre kullanımı</b>\n"
            "• Bir mesaja yanıt: <code>/filter Aleyküm selam</code> (tetikleyici yanıtladığın mesaj)\n"
            "• Yanıtsız: <code>/filter selam Aleyküm selam</code>\n"
            "• Çok kelimeli: <code>/filter \"iyi akşamlar\" Size de!</code>\n"
            "• Mesajın içinde geçerse: <code>/filter *selam* Merhaba!</code>\n"
            "• Sticker/foto/GIF ile cevap: medyaya yanıtla → <code>/filter selam</code>\n"
            "• Butonlar: cevabın altına satır satır <code>Kanal - https://t.me/kanal</code>\n"
            "Değişkenler: <code>{kullanıcı}</code> <code>{ad}</code> <code>{grup}</code> · Biçim (kalın, link…) korunur\n"
            "Liste: /filters · Sil: /stop selam · Hepsini sil: /stopall", parse_mode=ParseMode.HTML)
        return
    shown, norm, mode = parsed
    with get_db() as conn:
        exists = conn.execute("SELECT 1 FROM chat_filters WHERE chat_id = ? AND trigger_norm = ?", (chat_id, norm)).fetchone()
        count = conn.execute("SELECT COUNT(*) FROM chat_filters WHERE chat_id = ?", (chat_id,)).fetchone()[0]
    if not exists and count >= FILTER_LIMIT:
        await msg.reply_text(f"⚠️ Bu grupta en fazla {FILTER_LIMIT} filtre olabilir. /stop ile eskileri sil.")
        return
    async with _db_lock:
        with get_db() as conn:
            conn.execute("""INSERT OR REPLACE INTO chat_filters
                            (chat_id, trigger_norm, trigger_text, mode, reply_text, file_id, file_type, created_by, created_at,
                             is_html) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 1)""",
                         (chat_id, norm, shown, mode, (answer or '')[:3500], file_id, file_type,
                          update.effective_user.id, time.time()))
            conn.commit()
    _filter_changed(chat_id)
    how = "içinde geçince" if mode == 'contains' else "yazılınca"
    await msg.reply_text(f"✅ Filtre {'güncellendi' if exists else 'eklendi'}: <b>{html.escape(shown)}</b> {how} cevap verilecek.",
                         parse_mode=ParseMode.HTML)
    await send_log(chat_id, f"🧩 Filtre eklendi: {html.escape(shown)} | {mention(update.effective_user)}", ParseMode.HTML)

async def cmd_filters(update: Update, context):
    chat_id = _get_effective_chat_id(update, context)
    if not chat_id or not get_channel_settings(chat_id):
        await update.effective_message.reply_text("Önce /kanal ile grup seç!")
        return
    items = chat_filters(chat_id)
    if not items:
        await update.effective_message.reply_text("Bu grupta filtre yok. Eklemek için: /filter")
        return
    lines = [f"• {'*' if f['mode'] == 'contains' else ''}{html.escape(f['trigger_text'])}"
             f"{'*' if f['mode'] == 'contains' else ''}{' 🖼' if f['file_id'] else ''}" for f in
             sorted(items, key=lambda f: f['trigger_norm'])]
    await update.effective_message.reply_text(
        f"🧩 <b>Filtreler</b> ({len(items)})\n<blockquote expandable>" + "\n".join(lines) +
        "</blockquote>\nSilmek için: /stop &lt;tetikleyici&gt;", parse_mode=ParseMode.HTML)

async def cmd_stop_filter(update: Update, context):
    msg = update.effective_message
    chat_id = _get_effective_chat_id(update, context)
    if not chat_id or not get_channel_settings(chat_id):
        await msg.reply_text("Önce /kanal ile grup seç!")
        return
    if not await require(update, chat_id, 'can_filters'):
        return
    raw = (msg.text or '').split(maxsplit=1)
    trig = raw[1].strip().strip('"“”\'') if len(raw) > 1 else (msg.reply_to_message.text if msg.reply_to_message else '')
    parsed = _parse_trigger(trig or '')
    if not parsed:
        await msg.reply_text("Kullanım: /stop <tetikleyici>")
        return
    async with _db_lock:
        with get_db() as conn:
            n = conn.execute("DELETE FROM chat_filters WHERE chat_id = ? AND trigger_norm = ?", (chat_id, parsed[1])).rowcount
            conn.commit()
    _filter_changed(chat_id)
    await msg.reply_text("✅ Filtre silindi." if n else "Böyle bir filtre yok. /filters ile listeye bak.")

async def cmd_stopall(update: Update, context):
    msg = update.effective_message
    chat_id = _get_effective_chat_id(update, context)
    if not chat_id or not get_channel_settings(chat_id):
        await msg.reply_text("Önce /kanal ile grup seç!")
        return
    if not await require(update, chat_id, 'can_filters'):
        return
    n = len(chat_filters(chat_id))
    if not n:
        await msg.reply_text("Bu grupta filtre yok.")
        return
    await msg.reply_text(f"⚠️ Bu gruptaki <b>{n}</b> filtrenin hepsi silinsin mi?", parse_mode=ParseMode.HTML,
                         reply_markup=InlineKeyboardMarkup([[ibtn("🗑 Evet, hepsini sil", f"fall|{chat_id}|y", RED),
                                                             ibtn("↩️ Vazgeç", f"fall|{chat_id}|n")]]))

async def filter_clear_callback(update: Update, context):
    query = update.callback_query
    _, chat_id, ans = query.data.split('|')
    if not has_specific_permission(chat_id, query.from_user.id, 'can_filters'):
        await deny(update, 'can_filters')
        return
    await query.answer()
    if ans != 'y':
        await query.edit_message_text("Vazgeçildi.")
        return
    async with _db_lock:
        with get_db() as conn:
            n = conn.execute("DELETE FROM chat_filters WHERE chat_id = ?", (chat_id,)).rowcount
            conn.commit()
    _filter_changed(chat_id)
    await query.edit_message_text(f"🗑 {n} filtre silindi.")
    await send_log(chat_id, f"🧹 Tüm filtreler silindi ({n}) | {mention(query.from_user)}", ParseMode.HTML)

async def filter_reply_handler(update: Update, context):
    """Gruba gelen mesaj bir filtreyle eşleşirse bot cevap verir."""
    msg = update.effective_message
    if not msg or msg.chat.type == 'private':
        return
    text = msg.text or msg.caption
    if not text or text.startswith('/'):
        return
    chat_id = str(msg.chat_id)
    if not get_channel_settings(chat_id):
        return
    f = match_filter(chat_id, text)
    if not f:
        return
    key = (chat_id, f['trigger_norm'])
    now = time.time()
    if now - _filter_last.get(key, 0) < FILTER_COOLDOWN:
        return
    _filter_last[key] = now
    body = (f['reply_text'] or '') if f.get('is_html') else html.escape(f['reply_text'] or '', quote=False)
    rich = build_rich(body, {'type': f['file_type'], 'id': f['file_id']} if f['file_id'] else None)
    await send_rich(chat_id, rich, reply_msg=msg, users=[msg.from_user], title=msg.chat.title)

# ═══════════════════════════ KLON BOT ═══════════════════════════
# Akış: kullanıcı ana botta 🤖 Klon → BotFather token'ını gönderir → bot sahibine isteyen kişi, token ve bot ismi
# Onayla/Reddet ile gelir → onaylanırsa klon aynı altyapıyla açılır, reddedilirse açılmaz. Klon sahibi marka adı, karşılama metni, destek
# linki ve yardım başlığını değiştirebilir; kendi botunda /duyuru, /gban, /panel kullanır.
CLONE_TOKEN_RE = re.compile(r'^\d{6,12}:[A-Za-z0-9_-]{30,50}$')
CLONE_LIMIT_PER_USER = 1
CLONE_FIELDS = {  # alan: (etiket, istem, en fazla uzunluk)
    'brand':        ("🏷 Marka adı", "Botunun mesajlarda görünecek adını yaz (ör. Alfa Guard).", 32),
    'start_text':   ("👋 Karşılama metni", "/start yazınca görünecek karşılama metnini yaz.", 800),
    'support_link': ("🔗 Destek linki", "Destek grubu/kanal linkini yaz (https://t.me/...). Kaldırmak için: -", 120),
    'help_title':   ("❓ Yardım başlığı", "Yardım menüsünün başlığını yaz.", 60),
}

def clone_row(bot_id: int) -> dict | None:
    with get_db() as conn:
        r = conn.execute("SELECT * FROM clones WHERE bot_id = ?", (bot_id,)).fetchone()
    return dict(r) if r else None

def user_clones(user_id: int) -> list:
    with get_db() as conn:
        return [dict(r) for r in conn.execute(
            "SELECT * FROM clones WHERE owner_id = ? AND status != 'deleted' ORDER BY created_at", (user_id,))]

def pending_request(user_id: int) -> dict | None:
    """Kullanıcının bot sahibinin onayını bekleyen klon isteği."""
    with get_db() as conn:
        r = conn.execute("SELECT * FROM clone_requests WHERE user_id = ? AND status = 'pending' AND token IS NOT NULL "
                         "ORDER BY created_at DESC LIMIT 1", (user_id,)).fetchone()
    return dict(r) if r else None

def _mask_token(token: str | None) -> str:
    return f"{(token or '').split(':')[0]}:••••••" if token else "-"

def _clone_req_text(r: dict, decided: str = '') -> str:
    """Bot sahibine giden onay mesajı. Karar verilince token gizlenir."""
    who = f"@{html.escape(r['username'])}" if r.get('username') else html.escape(r.get('first_name') or 'Kullanıcı')
    tok = _mask_token(r.get('token')) if decided else (r.get('token') or '-')
    text = (f"🤖 <b>Klon bot onayı</b> #{r['id']}\n\n"
            f"👤 Botu açmak isteyen kişi: {who} — ID: <code>{r['user_id']}</code>\n"
            f"🔑 Bot token: <code>{html.escape(tok)}</code>\n"
            f"🏷 Bot ismi: {html.escape(r.get('bot_name') or '-')} (@{html.escape(r.get('bot_username') or '?')})")
    return text + (f"\n\n— {decided}" if decided else "")

async def _edit_req_msg(r: dict, decided: str):
    if not r.get('admin_msg_id'):
        return
    try:
        await (MAIN_BOT or bot).edit_message_text(_clone_req_text(r, decided), chat_id=FOUNDER_ID,
                                                  message_id=r['admin_msg_id'], parse_mode=ParseMode.HTML)
    except Exception as e:
        logger.debug(f"Klon isteği mesajı güncellenemedi: {e}")

async def _main_send(chat_id, text, **kw):
    """Ana bottan mesaj (klon bildirimleri, bot sahibine istekler). Gönderilemezse sessizce geçer."""
    try:
        return await (MAIN_BOT or bot).send_message(chat_id, text, **kw)
    except Exception as e:
        logger.debug(f"Ana bot mesajı gönderilemedi {chat_id}: {e}")

async def start_clone(row: dict) -> str | None:
    """Klonu başlatır. Hata metni ya da None döner."""
    bid = row['bot_id']
    if bid in CLONE_APPS:
        return None
    app = (Application.builder().token(row['token']).rate_limiter(UlusRateLimiter(max_retries=3))
           .job_queue(UlusJobQueue()).concurrent_updates(CONCURRENT_UPDATES).build())
    register_handlers(app, main_bot=False)
    try:
        await app.initialize()
    except (InvalidToken, Forbidden) as e:
        logger.warning(f"Klon başlatılamadı {bid}: {e}")
        return "Token geçersiz veya iptal edilmiş."
    except TelegramError as e:
        logger.warning(f"Klon başlatılamadı {bid}: {e}")
        return friendly_error(e)
    if app.bot.id != bid:
        await app.shutdown()
        return "Token başka bir bota ait."
    CLONES[bid] = row
    RUNNING_BOTS[bid] = app.bot
    CLONE_APPS[bid] = app
    token = _ctx_bot.set(app.bot)
    try:
        await setup_bot_profile(app.bot)
    finally:
        _ctx_bot.reset(token)
    await app.start()
    await app.updater.start_polling(allowed_updates=Update.ALL_TYPES)
    with get_db() as conn:
        conn.execute("UPDATE clones SET status = 'active', username = ?, name = ? WHERE bot_id = ?",
                     (app.bot.username, app.bot.first_name, bid))
        conn.commit()
    CLONES[bid] = clone_row(bid)
    logger.info(f"Klon çalışıyor: @{app.bot.username} (sahip {row['owner_id']})")
    return None

async def stop_clone(bid: int, status: str = 'stopped'):
    app = CLONE_APPS.pop(bid, None)
    RUNNING_BOTS.pop(bid, None)
    CLONES.pop(bid, None)
    if app:
        try:
            if app.updater and app.updater.running:
                await app.updater.stop()
            if app.running:
                await app.stop()
            await app.shutdown()
        except Exception as e:
            logger.debug(f"Klon durdurma {bid}: {e}")
    with get_db() as conn:
        conn.execute("UPDATE clones SET status = ? WHERE bot_id = ?", (status, bid))
        conn.commit()

async def start_all_clones():
    with get_db() as conn:
        rows = [dict(r) for r in conn.execute("SELECT * FROM clones WHERE status = 'active'")]
    for row in rows:
        err = await start_clone(row)
        if err:
            await _clone_invalid(row, err)

async def stop_all_clones():
    for bid in list(CLONE_APPS):
        app = CLONE_APPS.pop(bid)
        RUNNING_BOTS.pop(bid, None)
        try:
            if app.updater and app.updater.running:
                await app.updater.stop()
            if app.running:
                await app.stop()
            await app.shutdown()
        except Exception as e:
            logger.debug(f"Klon kapatma {bid}: {e}")

async def _clone_invalid(row: dict, why: str):
    await stop_clone(row['bot_id'], 'invalid')
    text = (f"⚠️ Klon botun @{html.escape(row.get('username') or str(row['bot_id']))} durduruldu: {html.escape(why)}\n"
            "BotFather'dan yeni token alıp 🤖 Klon menüsünden <b>Token değiştir</b> ile tekrar başlatabilirsin.")
    for uid in {row['owner_id'], FOUNDER_ID}:
        try:
            await _main_send(uid, text, parse_mode=ParseMode.HTML)
        except Exception as e:
            logger.debug(f"Klon uyarısı gönderilemedi {uid}: {e}")

async def clone_health_job(context):
    """Token iptal edilmiş/silinmiş klonları durdurur ve sahibine haber verir."""
    for bid, app in list(CLONE_APPS.items()):
        try:
            await app.bot.get_me()
        except (InvalidToken, Forbidden) as e:
            row = CLONES.get(bid) or clone_row(bid)
            if row:
                await _clone_invalid(row, f"token geçersiz ({e})")
        except TelegramError:
            pass

def _clone_menu(user_id: int):
    mine = user_clones(user_id)
    pend = pending_request(user_id)
    rows = []
    wait = (f"\n\n⏳ <b>@{html.escape(pend.get('bot_username') or '?')}</b> bot sahibinin onayını bekliyor. "
            "Onaylanınca açılacak.") if pend else ""
    if not mine:
        text = ("🤖 <b>Klon bot</b>\n\nKendi bot adınla, ULUS altyapısını kullanan bir koruma botu aç.\n"
                "1) @BotFather'da /newbot ile bot oluştur\n2) Aldığın token'ı aşağıdaki butonla gönder\n"
                "3) Bot sahibi onaylayınca botun çalışmaya başlar" + wait)
        rows.append([ibtn("↩️ İsteği geri çek", "cl|cancel", RED)] if pend else [ibtn("🔑 Token gönder", "cl|tok", GREEN)])
        return text, InlineKeyboardMarkup(rows)
    c = mine[0]
    st = {'active': "🟢 Çalışıyor", 'stopped': "⏸ Durduruldu", 'invalid': "⚠️ Token geçersiz"}.get(c['status'], c['status'])
    with get_db() as conn:
        n = conn.execute("SELECT COUNT(*) FROM channels WHERE bot_id = ?", (c['bot_id'],)).fetchone()[0]
    text = (f"🤖 <b>Klon botun</b>: @{html.escape(c.get('username') or '?')}\nDurum: {st} · Grup/kanal: {n}\n\n"
            f"🏷 Marka: <b>{html.escape(c.get('brand') or c.get('name') or '-')}</b>\n"
            f"🔗 Destek: {html.escape(c.get('support_link') or '-')}\n"
            f"❓ Yardım başlığı: {html.escape(c.get('help_title') or '-')}\n"
            f"👋 Karşılama: {html.escape((c.get('start_text') or 'varsayılan')[:80])}" + wait)
    b = c['bot_id']
    rows = [[ibtn(CLONE_FIELDS[f][0], f"cl|ed|{b}|{f}", BLUE) for f in ('brand', 'start_text')],
            [ibtn(CLONE_FIELDS[f][0], f"cl|ed|{b}|{f}", BLUE) for f in ('support_link', 'help_title')],
            [ibtn("⏸ Durdur", f"cl|stop|{b}", RED) if c['status'] == 'active' else ibtn("▶️ Başlat", f"cl|go|{b}", GREEN),
             ibtn("↩️ İsteği geri çek", "cl|cancel", RED) if pend else ibtn("🔑 Token değiştir", "cl|tok", BLUE)],
            [ibtn("🗑 Klonu sil", f"cl|del|{b}", RED)]]
    return text, InlineKeyboardMarkup(rows)

async def cmd_klon(update: Update, context):
    """/klon — klon bot menüsü (sadece ana botta, özelden)."""
    if update.effective_chat.type != 'private':
        await update.effective_message.reply_text("Klon işlemleri bota özelden yapılır.")
        return
    text, markup = _clone_menu(update.effective_user.id)
    await update.effective_message.reply_text(text, reply_markup=markup, parse_mode=ParseMode.HTML)

async def _decide_clone_request(query, rid: int, approve: bool):
    """Bot sahibi Onayla/Reddet'e bastı. Onay → klon açılır; red → açılmaz, token silinir."""
    with get_db() as conn:
        r = conn.execute("SELECT * FROM clone_requests WHERE id = ?", (rid,)).fetchone()
    r = dict(r) if r else None
    if not r or r['status'] != 'pending':
        await query.answer("Bu istek zaten işlendi.", show_alert=True)
        return
    if not r.get('token'):  # eski sürümden kalan izin isteği
        with get_db() as conn:
            conn.execute("UPDATE clone_requests SET status = 'cancelled', decided_at = ? WHERE id = ?", (time.time(), rid))
            conn.commit()
        await query.answer("Eski sürümden kalan istek; kullanıcı /klon ile token göndermeli.", show_alert=True)
        await _main_send(r['user_id'], "🤖 Klon sistemi yenilendi: /klon yazıp bot token'ını gönder, bot sahibi onaylayınca botun açılır.")
        return
    if approve:
        err, me_username = await _activate_clone(r['user_id'], r['token'], r['bot_id'])
        if err:
            with get_db() as conn:
                conn.execute("UPDATE clone_requests SET status = 'failed', token = NULL, decided_at = ? WHERE id = ?",
                             (time.time(), rid))
                conn.commit()
            await query.answer(f"Açılamadı: {err}"[:190], show_alert=True)
            await _edit_req_msg(r, f"⚠️ Açılamadı: {html.escape(err)}")
            await _main_send(r['user_id'], f"⚠️ Klon botun açılamadı: {html.escape(err)}\n/klon ile yeni token gönderebilirsin.",
                             parse_mode=ParseMode.HTML)
            return
        status, decided = 'approved', "✅ Onaylandı, bot açıldı"
    else:
        status, decided = 'rejected', "❌ Reddedildi"
    with get_db() as conn:
        conn.execute("UPDATE clone_requests SET status = ?, token = NULL, decided_at = ? WHERE id = ?", (status, time.time(), rid))
        conn.commit()
    await query.answer(decided)
    await _edit_req_msg(r, decided)
    if approve:
        await _main_send(r['user_id'],
            f"✅ <b>Klon botun onaylandı ve açıldı!</b> @{html.escape(me_username)}\n\n"
            f"Gruba eklemek için: https://t.me/{me_username}?startgroup=ulus&admin={ADMIN_RIGHTS_GROUP}\n"
            "Ad, karşılama metni ve destek linki için: /klon", parse_mode=ParseMode.HTML)
    else:
        await _main_send(r['user_id'], f"❌ @{r.get('bot_username') or '?'} için klon bot isteğin reddedildi.")

async def clone_callback(update: Update, context):
    """cl|... — klon menüsü ve bot sahibinin onay/yönetim butonları."""
    query = update.callback_query
    parts = query.data.split('|')
    op = parts[1]
    uid = query.from_user.id
    if op == 'req':  # eski sürümün "izin iste" butonu
        await query.answer("Artık izin istemene gerek yok: token'ı gönder, bot sahibi onaylayınca botun açılır.", show_alert=True)
    elif op in ('ok', 'no'):
        if uid != FOUNDER_ID:
            await query.answer("Bu işlemi sadece bot sahibi yapabilir.", show_alert=True)
            return
        await _decide_clone_request(query, int(parts[2]), op == 'ok')
        if query.message and query.message.chat.id == uid and len(parts) > 3:  # /klonlar listesinden basıldıysa
            text, markup = _clones_admin_view()
            try:
                await query.edit_message_text(text, reply_markup=markup, parse_mode=ParseMode.HTML)
            except BadRequest:
                pass
        return
    elif op == 'cancel':
        pend = pending_request(uid)
        if not pend:
            await query.answer("Bekleyen isteğin yok.", show_alert=True)
        else:
            with get_db() as conn:
                conn.execute("UPDATE clone_requests SET status = 'cancelled', token = NULL, decided_at = ? WHERE id = ?",
                             (time.time(), pend['id']))
                conn.commit()
            await _edit_req_msg(pend, "↩️ Kullanıcı isteği geri çekti")
            await query.answer("↩️ İstek geri çekildi")
    elif op == 'tok':
        context.user_data['await_clone'] = {'field': 'token', 'expires': time.time() + 600}
        await query.answer()
        await query.message.reply_text("🔑 @BotFather'dan aldığın bot token'ını yaz (ör. <code>123456789:ABC...</code>).\n"
                                       "Vazgeçmek için: iptal", parse_mode=ParseMode.HTML,
                                       reply_markup=ForceReply(input_field_placeholder="123456789:ABC..."))
        return
    elif op in ('ed', 'stop', 'go', 'del', 'delok', 'adm'):
        bid = int(parts[2])
        row = clone_row(bid)
        if not row or (row['owner_id'] != uid and uid != FOUNDER_ID):
            await query.answer("Bu klon senin değil.", show_alert=True)
            return
        if op == 'ed':
            field = parts[3]
            if field not in CLONE_FIELDS:
                await query.answer("Geçersiz.", show_alert=True)
                return
            context.user_data['await_clone'] = {'field': field, 'bot_id': bid, 'expires': time.time() + 600}
            await query.answer()
            await query.message.reply_text(f"{CLONE_FIELDS[field][1]}\nVazgeçmek için: iptal",
                                           reply_markup=ForceReply(input_field_placeholder=CLONE_FIELDS[field][0]))
            return
        if op == 'stop':
            await stop_clone(bid)
            await query.answer("⏸ Durduruldu")
        elif op == 'go':
            if row['status'] == 'deleted' or not row['token']:
                await query.answer("Bu klon silinmiş.", show_alert=True)
                return
            err = await start_clone(row)
            if err:
                await query.answer(err[:190], show_alert=True)
                return
            await query.answer("▶️ Başlatıldı")
        elif op == 'del':
            await query.answer()
            await query.edit_message_text(f"🗑 @{html.escape(row.get('username') or '')} klonu silinsin mi? Bot durur, "
                                          "gruplardaki ayarlar kalır.", parse_mode=ParseMode.HTML,
                                          reply_markup=InlineKeyboardMarkup([[ibtn("🗑 Evet, sil", f"cl|delok|{bid}", RED),
                                                                              ibtn("↩️ Vazgeç", f"cl|adm|{bid}")]]))
            return
        elif op == 'delok':
            await stop_clone(bid, 'deleted')
            with get_db() as conn:
                conn.execute("UPDATE clones SET token = '' WHERE bot_id = ?", (bid,))
                conn.commit()
            await query.answer("🗑 Silindi")
            if uid != row['owner_id']:
                await _main_send(row['owner_id'], f"🗑 Klon botun @{row.get('username')} bot sahibi tarafından silindi.")
        else:
            await query.answer()
        if uid == FOUNDER_ID and uid != row['owner_id']:
            text, markup = _clones_admin_view()
        else:
            text, markup = _clone_menu(uid)
        await query.edit_message_text(text, reply_markup=markup, parse_mode=ParseMode.HTML)
        return
    else:
        await query.answer()
        return
    text, markup = _clone_menu(uid)
    try:
        await query.edit_message_text(text, reply_markup=markup, parse_mode=ParseMode.HTML)
    except BadRequest:
        pass

async def clone_input_handler(update: Update, context):
    """Klon için beklenen metin girişi (token / özelleştirme alanı). Sadece özelden ve bekleyen giriş varsa."""
    pend = context.user_data.get('await_clone')
    msg = update.effective_message
    if not pend or update.effective_chat.type != 'private' or not msg or not msg.text:
        return
    if time.time() > pend['expires']:
        context.user_data.pop('await_clone', None)
        return
    text = msg.text.strip()
    if text.lower() in ('iptal', 'vazgeç', 'vazgec', '/iptal'):
        context.user_data.pop('await_clone', None)
        await msg.reply_text("Vazgeçildi.")
        raise ApplicationHandlerStop
    uid = update.effective_user.id
    if pend['field'] == 'token':
        context.user_data.pop('await_clone', None)
        try:
            await msg.delete()  # token sohbette açık kalmasın
        except TelegramError:
            pass
        reply = await _submit_clone_token(update.effective_user, text)
        await context.bot.send_message(uid, reply, parse_mode=ParseMode.HTML)
        t, mk = _clone_menu(uid)
        await context.bot.send_message(uid, t, reply_markup=mk, parse_mode=ParseMode.HTML)
        raise ApplicationHandlerStop
    field, bid = pend['field'], pend['bot_id']
    row = clone_row(bid)
    if not row or (row['owner_id'] != uid and uid != FOUNDER_ID):
        context.user_data.pop('await_clone', None)
        raise ApplicationHandlerStop
    limit = CLONE_FIELDS[field][2]
    value = '' if text == '-' else text[:limit]
    if field == 'support_link' and value and not re.match(r'^https://t\.me/[\w/+\-]+$', value):
        await msg.reply_text("Link https://t.me/ ile başlamalı. Tekrar yaz ya da iptal.")
        raise ApplicationHandlerStop
    with get_db() as conn:
        conn.execute(f"UPDATE clones SET {field} = ? WHERE bot_id = ?", (value or None, bid))
        conn.commit()
    if bid in CLONES:
        CLONES[bid] = clone_row(bid)
    context.user_data.pop('await_clone', None)
    await msg.reply_text(f"✅ {CLONE_FIELDS[field][0]} güncellendi.")
    t, mk = _clone_menu(row['owner_id'] if uid == FOUNDER_ID else uid)
    await msg.reply_text(t, reply_markup=mk, parse_mode=ParseMode.HTML)
    raise ApplicationHandlerStop

async def _submit_clone_token(user, token: str) -> str:
    """Token'ı doğrular ve bot sahibine onaya gönderir (bot sahibinin kendi klonu doğrudan açılır)."""
    uid = user.id
    if not CLONE_TOKEN_RE.match(token):
        return "❌ Bu bir bot token'ına benzemiyor. @BotFather'daki tam token'ı gönder."
    if token == TOKEN:
        return "❌ Bu ana botun token'ı."
    try:
        me = await Bot(token).get_me()
    except (InvalidToken, Forbidden):
        return "❌ Token geçersiz. @BotFather'dan doğru token'ı kopyala."
    except TelegramError as e:
        return friendly_error(e)
    if me.id == BOT_ID:
        return "❌ Bu ana botun token'ı."
    existing = clone_row(me.id)
    if existing and existing['owner_id'] != uid and existing['status'] != 'deleted':
        return "❌ Bu bot zaten başka birinin klonu."
    with get_db() as conn:
        other = conn.execute("SELECT 1 FROM clone_requests WHERE bot_id = ? AND status = 'pending' AND user_id != ?",
                             (me.id, uid)).fetchone()
    if other:
        return "❌ Bu bot için başka birinin bekleyen isteği var."
    if uid == FOUNDER_ID:
        err, uname = await _activate_clone(uid, token, me.id)
        if err:
            return f"❌ Bot başlatılamadı: {html.escape(err)}"
        return (f"✅ <b>Klon botun hazır!</b> @{html.escape(uname)}\n\n"
                f"Gruba eklemek için: https://t.me/{uname}?startgroup=ulus&admin={ADMIN_RIGHTS_GROUP}")
    old = pending_request(uid)
    async with _db_lock:
        with get_db() as conn:
            if old:  # aynı kişinin önceki bekleyen isteği: yenisi geçerli
                conn.execute("UPDATE clone_requests SET status = 'cancelled', token = NULL, decided_at = ? WHERE id = ?",
                             (time.time(), old['id']))
            rid = conn.execute("""INSERT INTO clone_requests (user_id, username, first_name, status, created_at,
                                  bot_id, token, bot_username, bot_name) VALUES (?, ?, ?, 'pending', ?, ?, ?, ?, ?)""",
                               (uid, user.username, user.first_name, time.time(), me.id, token, me.username,
                                me.first_name)).lastrowid
            conn.commit()
            r = dict(conn.execute("SELECT * FROM clone_requests WHERE id = ?", (rid,)).fetchone())
    if old:
        await _edit_req_msg(old, "↩️ Yerine yeni istek gönderildi")
    sent = await _main_send(FOUNDER_ID, _clone_req_text(r), parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(
        [[ibtn("✅ Onayla", f"cl|ok|{rid}", GREEN), ibtn("❌ Reddet", f"cl|no|{rid}", RED)]]))
    if sent is not None and getattr(sent, 'message_id', None):
        with get_db() as conn:
            conn.execute("UPDATE clone_requests SET admin_msg_id = ? WHERE id = ?", (sent.message_id, rid))
            conn.commit()
    return (f"📨 <b>@{html.escape(me.username)}</b> için isteğin bot sahibine gönderildi.\n"
            "Onaylanınca botun açılacak ve sana haber vereceğim.")

async def _activate_clone(uid: int, token: str, bot_id: int):
    """Onaylanan token ile klonu kaydeder ve başlatır. Dönüş: (hata | None, kullanıcı adı)."""
    try:
        me = await Bot(token).get_me()
    except (InvalidToken, Forbidden):
        return "Token geçersiz veya iptal edilmiş.", ''
    except TelegramError as e:
        return friendly_error(e), ''
    if me.id != bot_id:
        return "Token başka bir bota ait.", ''
    existing = clone_row(me.id)
    if existing and existing['owner_id'] != uid and existing['status'] != 'deleted':
        return "Bu bot zaten başka birinin klonu.", ''
    mine = [c for c in user_clones(uid) if c['bot_id'] != me.id]
    old = mine[0] if mine else None
    if old and uid != FOUNDER_ID and len(mine) >= CLONE_LIMIT_PER_USER:
        await stop_clone(old['bot_id'], 'deleted')  # token değiştir = eski klonun yerine yenisi
    async with _db_lock:
        with get_db() as conn:
            conn.execute("""INSERT INTO clones (bot_id, owner_id, token, username, name, status, created_at)
                            VALUES (?, ?, ?, ?, ?, 'active', ?)
                            ON CONFLICT(bot_id) DO UPDATE SET token = excluded.token, owner_id = excluded.owner_id,
                            username = excluded.username, name = excluded.name, status = 'active'""",
                         (me.id, uid, token, me.username, me.first_name, time.time()))
            if old:
                for col in ('brand', 'start_text', 'support_link', 'help_title'):
                    conn.execute(f"UPDATE clones SET {col} = COALESCE({col}, ?) WHERE bot_id = ?", (old.get(col), me.id))
                if uid != FOUNDER_ID:
                    conn.execute("UPDATE clones SET token = '' WHERE bot_id = ?", (old['bot_id'],))
            conn.commit()
    if me.id in CLONE_APPS:  # aynı bot yeni token'la: yeniden başlat
        await stop_clone(me.id, 'active')
    err = await start_clone(clone_row(me.id))
    return err, me.username

def _clones_admin_view():
    with get_db() as conn:
        rows = [dict(r) for r in conn.execute("SELECT * FROM clones WHERE status != 'deleted' ORDER BY created_at")]
        pend = [dict(r) for r in conn.execute("SELECT * FROM clone_requests WHERE status = 'pending' AND token IS NOT NULL "
                                              "ORDER BY created_at")]
    icon = {'active': "🟢", 'stopped': "⏸", 'invalid': "⚠️"}
    lines = [f"{icon.get(r['status'], '•')} @{html.escape(r.get('username') or '?')} — sahip <code>{r['owner_id']}</code>"
             for r in rows]
    plines = [f"⏳ @{html.escape(p.get('bot_username') or '?')} — isteyen <code>{p['user_id']}</code>" for p in pend]
    text = (f"🤖 <b>Klon botlar</b> ({len(rows)}) · Onay bekleyen: {len(pend)}\n\n" + ("\n".join(lines) or "Henüz klon yok.")
            + ("\n\n<b>Onay bekleyenler</b>\n" + "\n".join(plines) if plines else ""))
    kb = []
    for p in pend[:10]:
        kb.append([ibtn(f"⏳ @{(p.get('bot_username') or '?')[:18]}", f"cl|ok|{p['id']}|l", GREEN),
                   ibtn("❌", f"cl|no|{p['id']}|l", RED)])
    for r in rows[:30]:
        b = r['bot_id']
        kb.append([ibtn(f"@{(r.get('username') or '?')[:20]}", f"cl|adm|{b}"),
                   ibtn("⏸" if r['status'] == 'active' else "▶️", f"cl|{'stop' if r['status'] == 'active' else 'go'}|{b}",
                        RED if r['status'] == 'active' else GREEN),
                   ibtn("🗑", f"cl|del|{b}", RED)])
    return text, InlineKeyboardMarkup(kb) if kb else None

async def cmd_klonlar(update: Update, context):
    """/klonlar — bot sahibi: tüm klonları listele, durdur/başlat/sil."""
    if update.effective_user.id != FOUNDER_ID:
        return
    text, markup = _clones_admin_view()
    await update.effective_message.reply_text(text, reply_markup=markup, parse_mode=ParseMode.HTML)

# ── Veritabanı yedekleme ──
def _make_backup() -> str:
    os.makedirs(BACKUP_DIR, exist_ok=True)
    path = os.path.join(BACKUP_DIR, f"bot_data_{datetime.now(TZ_TR):%Y%m%d_%H%M}.db")
    src_conn = sqlite3.connect(DB_FILE)
    dst_conn = sqlite3.connect(path)
    try:
        src_conn.backup(dst_conn)  # çalışırken güvenli kopya
    finally:
        dst_conn.close()
        src_conn.close()
    files = sorted(f for f in os.listdir(BACKUP_DIR) if f.startswith('bot_data_') and f.endswith('.db'))
    for old in files[:-BACKUP_KEEP]:
        try:
            os.remove(os.path.join(BACKUP_DIR, old))
        except OSError:
            pass
    return path

def _zip_backup(path: str) -> str:
    import zipfile
    zpath = path[:-3] + ".zip"
    with zipfile.ZipFile(zpath, 'w', zipfile.ZIP_DEFLATED, compresslevel=6) as z:
        z.write(path, os.path.basename(path))
    return zpath

async def backup_job(context: ContextTypes.DEFAULT_TYPE):
    try:
        path = await asyncio.to_thread(_make_backup)
        logger.info(f"Yedek alındı: {path}")
        if not BACKUP_CHAT_ID:
            return
        zpath = await asyncio.to_thread(_zip_backup, path)
        size = os.path.getsize(zpath)
        if size < 45 * 1024 * 1024:
            with open(zpath, 'rb') as f:
                await context.bot.send_document(
                    BACKUP_CHAT_ID, f, filename=os.path.basename(zpath),
                    caption=f"🗄 Veritabanı yedeği · {os.path.getsize(path) / 1048576:.1f} MB "
                            f"(sıkıştırılmış {size / 1048576:.1f} MB)\nGeri yüklemek için zip'teki .db dosyasını "
                            f"bot_data.db adıyla bot klasörüne koy.")
        else:
            await context.bot.send_message(BACKUP_CHAT_ID, f"🗄 Yedek alındı ama Telegram'a sığmıyor "
                                                           f"({size / 1048576:.0f} MB): {path}")
        try:
            os.remove(zpath)
        except OSError:
            pass
    except Exception as e:
        logger.error(f"Yedekleme hatası: {e}")

async def cmd_yedek(update: Update, context):
    if update.effective_user.id != FOUNDER_ID:
        return
    await update.effective_message.reply_text("🗄 Yedek alınıyor...")
    await backup_job(context)

def _cleanup_in_memory_caches(now: float) -> None:
    # Süresiz büyüyebilen sözlükler için yaş temelli temizlik
    for dct, ttl in ((_settings_cache, SETTINGS_CACHE_TTL * 5), (_tg_admin_cache, TG_ADMIN_CACHE_TTL * 5), (_title_cache, 3600)):
        for k, v in list(dct.items()):
            ts = v[0] if isinstance(v, tuple) and v else 0
            if ts and now - ts > ttl:
                dct.pop(k, None)

    for dct, ttl in ((_report_last, 6 * 3600), (_filter_last, 600), (_unregistered_checked, 2 * 3600), (_demotion_alerted, 3600)):
        for k, ts in list(dct.items()):
            if isinstance(ts, (int, float)) and now - ts > ttl:
                dct.pop(k, None)

    for dct, ttl in ((_media_attack, 600), (_channel_media_hits, 1200), (_flood_data, 600)):
        for k, vals in list(dct.items()):
            if not isinstance(vals, list):
                continue
            fresh = [x for x in vals if isinstance(x, (int, float)) and now - x < ttl]
            if fresh:
                dct[k] = fresh
            else:
                dct.pop(k, None)

    for k, vals in list(_demotions.items()):
        if not isinstance(vals, list):
            _demotions.pop(k, None)
            continue
        fresh = [(t, u) for t, u in vals if isinstance(t, (int, float)) and now - t < 1200]
        if fresh:
            _demotions[k] = fresh
        else:
            _demotions.pop(k, None)

# ── Periyodik temizlik ──
async def db_cleanup_job(context: ContextTypes.DEFAULT_TYPE):
    flush_writes()  # bekleyen toplu yazmalar okunmadan önce yazılır
    now = time.time()
    msg_stats_cutoff = now - (MESSAGE_STATS_RETENTION_DAYS * 86400)
    async with _db_lock:
        with get_db() as conn:
            conn.execute("DELETE FROM flood_history WHERE timestamp < ?", (now - 86400,))
            conn.execute("DELETE FROM media_flood_history WHERE timestamp < ?", (now - 86400,))
            conn.execute("DELETE FROM forward_history WHERE timestamp < ?", (now - 86400,))
            conn.execute("DELETE FROM raid_joins WHERE timestamp < ?", (now - 86400,))
            conn.execute("DELETE FROM spam_incidents WHERE incident_at < ?", (now - 30 * 86400,))
            conn.execute("DELETE FROM newcomers WHERE joined_at < ?", (now - 2 * 86400,))
            conn.execute("DELETE FROM appeals WHERE created_at < ? AND status != 'pending'", (now - 90 * 86400,))
            conn.execute("DELETE FROM msg_cache WHERE sent_at < ?", (now - 2 * 86400,))
            conn.execute("DELETE FROM msg_edits WHERE at < ?", (now - EDIT_HISTORY_KEEP_DAYS * 86400,))
            conn.execute("DELETE FROM admin_actions WHERE at < ?", (now - AUDIT_KEEP_DAYS * 86400,))
            conn.execute("DELETE FROM reports WHERE created_at < ?", (now - 30 * 86400,))
            conn.execute("DELETE FROM message_stats WHERE sent_at < ?", (msg_stats_cutoff,))
            conn.commit()
    _cleanup_in_memory_caches(now)

# ── Genel hata yakalayıcı ──
_last_error_notify = 0.0

async def error_handler(update: object, context: ContextTypes.DEFAULT_TYPE):
    global _last_error_notify
    err = context.error
    if isinstance(err, (Forbidden,)):
        logger.info(f"Yetki/erişim hatası (yok sayıldı): {err}")
        return
    if isinstance(err, BadRequest) and any(s in str(err).lower() for s in (
            'message to delete not found', 'message is not modified', 'query is too old', "message can't be deleted")):
        return
    logger.error("İşlenmeyen hata", exc_info=err)
    now = time.time()
    if FOUNDER_ID and now - _last_error_notify > 60:  # dakikada en fazla 1 bildirim
        _last_error_notify = now
        tb = ''.join(traceback.format_exception(type(err), err, err.__traceback__))[-3000:]
        where = ''
        if isinstance(update, Update) and update.effective_chat:
            where = f"Sohbet: {update.effective_chat.id}\n"
        try:
            await (MAIN_BOT or context.bot).send_message(FOUNDER_ID, f"⚠️ Bot hatası\n{where}<pre>{html.escape(tb)}</pre>",
                                           parse_mode=ParseMode.HTML)
        except Exception:
            pass
    await _tell_user_about_error(update)

bad_callbacks: list = []  # testler için: geçersiz veri yüzünden durdurulan buton tıklamaları

def guard_callback(fn):
    """Buton verisi eski/bozuksa (ayrıştırma hatası) çökme yerine 'buton geçersiz' uyarısı verir."""
    @functools.wraps(fn)
    async def wrapper(update, context):
        try:
            return await fn(update, context)
        except (ValueError, IndexError, KeyError, OverflowError) as e:
            data = getattr(update.callback_query, 'data', '')
            bad_callbacks.append((fn.__name__, data, repr(e)))
            logger.warning(f"Geçersiz buton verisi {fn.__name__} {data!r}: {e!r}")
            try:
                await update.callback_query.answer("⚠️ Bu buton eskimiş veya geçersiz. Menüyü yeniden aç.", show_alert=True)
            except TelegramError:
                pass
    return wrapper

async def _tell_user_about_error(update) -> None:
    """Beklenmeyen hatada kullanıcıya kısa ve kibar bir bilgi verir (ham hata metni gösterilmez)."""
    if not isinstance(update, Update):
        return
    text = "⚠️ Bir sorun oluştu, işlem tamamlanamadı. Lütfen tekrar dene."
    try:
        if update.callback_query:
            await update.callback_query.answer(text, show_alert=True)
        elif update.message and (update.effective_chat.type == 'private' or (update.message.text or '').startswith('/')):
            await update.message.reply_text(text)
    except TelegramError:
        pass

async def chat_member_cache_handler(update: Update, context):
    """Admin atama/alma olduğunda admin önbelleğini temizler. Telegram'dan elle ya da başka bir botla yönetici yapılan
    kişiye rütbe verilir (yetki alma rütbeyi otomatik silmez: toplu düşürme saldırısında rütbeler kaybolmasın; /reload siler)."""
    cm = update.chat_member
    if not cm:
        return
    chat_id = str(cm.chat.id)
    invalidate_admin_cache(chat_id)
    new = cm.new_chat_member
    if (new.status == 'administrator' and cm.old_chat_member.status != 'administrator' and not new.user.is_bot
            and get_channel_settings(chat_id) and not user_level(chat_id, new.user.id)):
        role = await auto_assign_role(chat_id, new.user.id, new)
        logger.info(f"Telegram'dan yönetici yapıldı, rütbe verildi {chat_id}/{new.user.id}: {role}")

RELOAD_COOLDOWN = 30
_reload_last: dict = {}

async def reload_admins(chat_id: str):
    """Telegram'daki güncel yönetici listesini bot kaydına işler: kurucu eşitlenir, rütbesi olmayan yöneticiye rütbe
    verilir, artık yönetici olmayanın rütbesi alınır (kurucu, botu ekleyen ve acil kilitte yetkisi alınanlar hariç).
    Dönüş: (eklenenler, kaldırılanlar, yönetici sayısı) veya liste alınamazsa None."""
    chat_id = str(chat_id)
    invalidate_admin_cache(chat_id)
    try:
        admins = await bot.get_chat_administrators(chat_id)
    except TelegramError as e:
        logger.debug(f"/reload admin listesi alınamadı {chat_id}: {e}")
        return None
    await sync_creator(chat_id, admins)
    people = [a for a in admins if not a.user.is_bot]
    added = []
    for a in people:
        if a.status == 'administrator' and not user_level(chat_id, a.user.id):
            await auto_assign_role(chat_id, a.user.id, a)
            added.append(a.user.id)
    keep = {a.user.id for a in people}
    with get_db() as conn:
        ch = conn.execute("SELECT owner_id, added_by FROM channels WHERE chat_id = ?", (chat_id,)).fetchone()
    if ch:
        keep |= {ch['owner_id'], ch['added_by']}
    try:
        keep |= set(json.loads(get_channel_cfg(chat_id).get('lockdown_saved_admins') or '[]'))
    except (ValueError, TypeError):
        pass
    async with _db_lock:
        with get_db() as conn:
            stale = [r['user_id'] for r in conn.execute(
                "SELECT user_id FROM roles WHERE chat_id = ? AND role != 'kurucu'", (chat_id,)) if r['user_id'] not in keep]
            for uid in stale:
                conn.execute("DELETE FROM roles WHERE chat_id = ? AND user_id = ?", (chat_id, uid))
            conn.commit()
    _invalidate_settings(chat_id)
    invalidate_admin_cache(chat_id)
    _tg_admin_cache[chat_id] = (time.time(), {a.user.id for a in admins})
    return added, stale, len(people)

async def cmd_reload(update: Update, context):
    """/reload — admin listesini Telegram'dan yeniden yükler (elle veya başka botlarla verilen/alınan yetkiler)."""
    msg = update.effective_message
    chat_id = _get_effective_chat_id(update, context)
    if not chat_id or not get_channel_settings(chat_id):
        await msg.reply_text("Önce /kanal ile grup seç!")
        return
    uid = update.effective_user.id if update.effective_user else 0
    is_anon = uid == GROUP_ANON_BOT_ID or (msg.sender_chat is not None and str(msg.sender_chat.id) == str(chat_id))
    if not (is_anon or user_level(chat_id, uid) or await _is_real_chat_admin(chat_id, uid)):
        await msg.reply_text("⛔ Bu komutu sadece yöneticiler kullanabilir.")
        return
    now = time.time()
    if now - _reload_last.get(chat_id, 0) < RELOAD_COOLDOWN:
        await msg.reply_text(f"⏳ Admin listesi az önce yenilendi. {RELOAD_COOLDOWN} sn sonra tekrar dene.")
        return
    _reload_last[chat_id] = now
    res = await reload_admins(chat_id)
    if res is None:
        await msg.reply_text("⚠️ Admin listesi alınamadı. Bot bu grupta yönetici mi?")
        return
    added, removed, total = res
    lines = [f"🔄 <b>Admin listesi yenilendi</b> — {total} yönetici"]
    if added:
        lines.append("➕ Rütbe verildi: " + ", ".join(f"<code>{u}</code>" for u in added[:20]))
    if removed:
        lines.append("➖ Rütbesi alındı (artık yönetici değil): " + ", ".join(f"<code>{u}</code>" for u in removed[:20]))
    if not added and not removed:
        lines.append("Kayıt zaten güncel.")
    await msg.reply_text("\n".join(lines), parse_mode=ParseMode.HTML)
    if added or removed:
        await send_log(chat_id, f"🔄 /reload: +{len(added)} / −{len(removed)} | {mention(update.effective_user)}", ParseMode.HTML)


async def _startup_report(b):
    """Açılışta veritabanı yolunu ve kayıtlı sohbet sayısını loglar ve bot sahibine bildirir."""
    with get_db() as conn:
        n = conn.execute("SELECT COUNT(*) FROM channels").fetchone()[0]
    size = os.path.getsize(DB_FILE) // 1024 if os.path.exists(DB_FILE) else 0
    text = (f"🟢 ULUS başladı\nVeritabanı: <code>{html.escape(DB_FILE)}</code> ({size} KB)\n"
            f"Kayıtlı grup/kanal: <b>{n}</b>")
    if RESTORED_FROM:
        text += f"\n⚠️ Veritabanı boş açıldı, son yedekten geri yüklendi: <code>{html.escape(RESTORED_FROM)}</code>"
    elif n == 0:
        text += ("\n⚠️ Kayıtlı sohbet yok. Bot yeniden başlatılınca bu sayı düşüyorsa veritabanı dosyası "
                 "silinmiş ya da farklı bir klasörden çalıştırılıyor olabilir.")
    logger.info(text.replace("<code>", "").replace("</code>", "").replace("<b>", "").replace("</b>", ""))
    if FOUNDER_ID:
        try:
            await b.send_message(FOUNDER_ID, text, parse_mode=ParseMode.HTML)
        except Exception as e:
            logger.debug(f"Açılış bildirimi gönderilemedi: {e}")

_unregistered_checked: dict = {}

async def ensure_registered(chat_id: str, chat_type: str | None = None) -> bool:
    """Bot yöneticisi olduğu ama kaydı olmayan sohbeti (ör. veritabanı kaybından sonra) otomatik kaydeder.
    Sahibi: Telegram'daki grup/kanal sahibi. Başarısız denemeler 10 dk boyunca tekrarlanmaz."""
    chat_id = str(chat_id)
    if get_channel_settings(chat_id):
        return True
    if time.time() - _unregistered_checked.get(chat_id, 0) < 600:
        return False
    _unregistered_checked[chat_id] = time.time()
    try:
        me = await bot.get_chat_member(chat_id, bot_id_for(chat_id))
        if me.status != 'administrator':
            return False
        admins = await bot.get_chat_administrators(chat_id)
        if not chat_type:
            chat_type = (await bot.get_chat(chat_id)).type
    except TelegramError as e:
        logger.debug(f"Otomatik kayıt kontrolü başarısız {chat_id}: {e}")
        return False
    creator = next((a.user.id for a in admins if getattr(a, 'status', None) == 'creator'), 0)
    await _register_chat(chat_id, creator, chat_type, added_by=None)
    _unregistered_checked.pop(chat_id, None)
    logger.info(f"Kaydı olmayan sohbet otomatik kaydedildi: {chat_id} (sahip {creator})")
    return True

async def repair_rank(chat_id: str, user_id: int) -> bool:
    """Telegram'da kurucu/yönetici olup bot kaydında rütbesi olmayan kişinin rütbesini onarır."""
    if user_level(chat_id, user_id):
        return True
    try:
        member = await bot.get_chat_member(chat_id, user_id)
    except TelegramError:
        return False
    if member.status == 'creator':
        await sync_creator(chat_id, [member])
        return True
    if member.status == 'administrator':
        await auto_assign_role(chat_id, user_id, member)
        return True
    return False

async def auto_register_handler(update: Update, context):
    """Grup/kanal güncellemesi kaydı olmayan bir sohbetten geldiyse (bot orada yöneticiyse) kaydeder."""
    chat = update.effective_chat
    if chat and chat.type in ('group', 'supergroup', 'channel') and not get_channel_settings(str(chat.id)):
        await ensure_registered(str(chat.id), chat.type)

async def checkpoint_job(context):
    """WAL dosyasındaki değişiklikleri ana veritabanı dosyasına yazar (yalnız .db kopyalansa da veri kaybolmaz)."""
    try:
        with get_db() as conn:
            conn.execute("PRAGMA wal_checkpoint(TRUNCATE)")
    except sqlite3.Error as e:
        logger.debug(f"WAL checkpoint: {e}")

async def post_shutdown(application):
    flush_writes()
    await stop_all_clones()
    await checkpoint_job(None)
    global userbot
    if userbot:
        try:
            await userbot.disconnect()
        except Exception as e:
            logger.debug(f"Telethon kapanış hatası: {e}")
        userbot = None
    logger.info("ULUS botu düzgün şekilde kapatıldı.")

async def post_init(application):
    global BOT_ID, userbot
    BOT_ID = application.bot.id
    RUNNING_BOTS[BOT_ID] = application.bot
    await setup_bot_profile(application.bot)
    await _startup_report(application.bot)
    try:
        await start_all_clones()
    except Exception as e:
        logger.error(f"Klonlar başlatılamadı: {e}")

    if not (USERBOT_API_ID and USERBOT_API_HASH):
        logger.info("API_ID / API_HASH boş — Telethon kapalı (kullanıcı adı çözme ve toplu istek onayı Bot API ile yapılır).")
        return
    try:
        userbot = TelegramClient(USERBOT_SESSION, USERBOT_API_ID, USERBOT_API_HASH)
        await userbot.start(bot_token=TOKEN)
        me = await userbot.get_me()
        logger.info(f"Telethon aktif: @{me.username} ({me.id})")
    except Exception as e:
        logger.error(f"Telethon başlatılamadı: {e}")
        userbot = None

